// Plus Two entrance chemistry bank: Electrochemistry (Class 12). Original fibub questions.
// Data used (25 °C): F = 96500 C/mol, 2.303RT/F = 0.059 V, R = 8.314 J/(mol K). E° (V, reduction): Li+ -3.05, K+ -2.93, Ca2+ -2.87, Na+ -2.71, Mg2+ -2.37, Al3+ -1.66, Zn2+ -0.76, Fe2+ -0.44, Cd2+ -0.40, Ni2+ -0.25, Sn2+ -0.14, Pb2+ -0.13, H+ 0.00, Cu2+ +0.34, I2 +0.54, Fe3+/Fe2+ +0.77, Ag+ +0.80, Br2 +1.09, Cl2 +1.36, Au3+ +1.50. Atomic masses: Cu 63.5, Ag 108, Zn 65, Al 27, Ni 58.7.
import { pick, int, choose, fmt, shuffleOpts, numOpts } from '../_entrance.js';

let _n = 0;
const EXM = { 1: ['keam', 'cusat', 'comedk', 'jee-main', 'neet', 'cuet'], 2: ['keam', 'cusat', 'comedk', 'jee-main', 'neet', 'cuet'], 3: ['jee-main', 'neet', 'comedk', 'cuet'], 4: ['jee-main', 'jee-adv', 'neet'], 5: ['jee-adv'] };
const EX = { 1: ['keam', 'cusat', 'comedk', 'jee-main', 'neet'], 2: ['keam', 'cusat', 'comedk', 'jee-main', 'neet'], 3: ['jee-main', 'neet', 'comedk'], 4: ['jee-main', 'jee-adv', 'neet'], 5: ['jee-adv'] };
const A4 = ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'];
const S4 = ['Both Statement I and Statement II are correct', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct', 'Both Statement I and Statement II are incorrect'];
const L = [];
const mkx = (level, sub, q, right, wrongs, sol, trap) => {
  const pos = (_n++) % 4; const options = [...wrongs]; options.splice(pos, 0, right);
  return { type: 'mcq', level, format: 'single', exams: EXM[level], sub, q, options, answer: pos, sol, ...(trap ? { trap } : {}) };
};
const mk = (...a) => { L.push(mkx(...a)); };
const nat = (level, sub, q, answer, tol, unit, sol, trap, calc) => { L.push({ type: 'nat', level, format: tol === 0 ? 'integer' : 'numeric', exams: EX[level], sub, q, answer, tol, ...(unit ? { unit } : {}), sol, ...(trap ? { trap } : {}), ...(calc ? { calc } : {}) }); };
const msq = (level, sub, q, options, answer, sol, trap) => { L.push({ type: 'msq', level, format: 'multi', exams: level >= 4 ? ['jee-adv'] : ['jee-adv', 'jee-main'], sub, q, options, answer, sol, ...(trap ? { trap } : {}) }); };
const asr = (level, sub, A, R, answer, sol, trap) => { L.push({ type: 'mcq', level, format: 'assertion', exams: EXM[level], sub, q: `<p><b>Assertion (A):</b> ${A}</p><p><b>Reason (R):</b> ${R}</p>`, options: A4, answer, sol, ...(trap ? { trap } : {}) }); };
const stm = (level, sub, s1, s2, answer, sol, trap) => { L.push({ type: 'mcq', level, format: 'statements', exams: EXM[level], sub, q: `<p><b>Statement I:</b> ${s1}</p><p><b>Statement II:</b> ${s2}</p>`, options: S4, answer, sol, ...(trap ? { trap } : {}) }); };
const mat = (level, sub, group, q, right, wrongs, sol, trap) => { L.push({ ...mkx(level, sub, q, right, wrongs, sol, trap), format: 'match', group }); };
const P = (level, sub, group, q, right, wrongs, sol, trap) => { L.push({ ...mkx(level, sub, q, right, wrongs, sol, trap), format: 'passage', group }); };
const PN = (level, sub, group, q, answer, tol, unit, sol, trap, calc) => { L.push({ type: 'nat', level, format: 'passage', exams: EX[level], sub, group, q, answer, tol, ...(unit ? { unit } : {}), sol, ...(trap ? { trap } : {}), ...(calc ? { calc } : {}) }); };
const l10 = Math.log10;
const F = 96500;
// ---------- Level 1 ----------
mk(1, 'galvanic cell', 'In a working galvanic cell, oxidation takes place at the', 'anode, which is the negative electrode', ['cathode, which is the negative electrode', 'anode, which is the positive electrode', 'cathode, which is the positive electrode'], '<p>Oxidation always happens at the anode. In a galvanic cell the anode is where electrons are released, so it is the negative pole. Reduction happens at the cathode, the positive pole. (In an electrolytic cell the signs flip, but oxidation is still at the anode.)</p>');
mk(1, 'salt bridge', 'The main job of a salt bridge in a galvanic cell is to', 'complete the circuit and keep both half-cells electrically neutral', ['carry electrons from anode to cathode', 'increase the emf of the cell', 'stop the electrodes from reacting'], '<p>Electrons travel only through the external wire. The salt bridge lets ions move between the two beakers, which closes the circuit and stops charge building up in either half-cell. It does not carry electrons and does not raise the emf.</p>');
nat(1, 'cell emf', 'Find the standard emf of the Daniell cell Zn|Zn<sup>2+</sup>(1 M)||Cu<sup>2+</sup>(1 M)|Cu. Take E&deg;(Zn<sup>2+</sup>/Zn) = -0.76 V and E&deg;(Cu<sup>2+</sup>/Cu) = +0.34 V.', 1.10, 0.01, 'V', '<p>E&deg;<sub>cell</sub> = E&deg;(cathode) - E&deg;(anode), both as reduction potentials.</p><p>Cu<sup>2+</sup> is reduced (cathode), Zn is oxidised (anode): 0.34 - (-0.76) = <b>1.10 V</b>.</p>', 'Do not change the sign of the anode value twice.', () => 0.34 + 0.76);
mk(1, 'SHE', 'By convention, the potential of the standard hydrogen electrode (SHE) is', 'zero at all temperatures', ['+1.00 V', '-0.76 V', '+0.34 V'], '<p>SHE is the reference. It is Pt in contact with H<sub>2</sub> gas at 1 bar and 1 M H<sup>+</sup>. Its potential is defined as 0.00 V, and every other electrode potential is measured against it.</p>');
mk(1, 'units of conductance', 'The SI-based unit usually written for molar conductivity (&Lambda;<sub>m</sub>) is', 'S cm<sup>2</sup> mol<sup>-1</sup>', ['S cm<sup>-1</sup>', 'ohm cm', 'S mol cm<sup>-2</sup>'], '<p>&Lambda;<sub>m</sub> = &kappa; &times; 1000 / c, where &kappa; is in S cm<sup>-1</sup> and c in mol L<sup>-1</sup>. The units work out to S cm<sup>2</sup> mol<sup>-1</sup>. S cm<sup>-1</sup> is the unit of conductivity &kappa;; ohm cm is resistivity.</p>');
mk(1, 'Faraday constant', 'One faraday (1 F) is the charge carried by', 'one mole of electrons, about 96500 C', ['one electron, about 1.6 &times; 10<sup>-19</sup> C', 'one mole of any ion, whatever its charge', 'one gram of electrons'], '<p>1 F = N<sub>A</sub> &times; e = 6.022 &times; 10<sup>23</sup> &times; 1.602 &times; 10<sup>-19</sup> &asymp; 96500 C per mole of electrons. A mole of Al<sup>3+</sup> carries 3 F, so option 3 is wrong.</p>');
mk(1, 'electrochemical series', 'Among Li, Cu, Ag and Zn, the strongest reducing agent (use the electrochemical series) is', 'Li', ['Cu', 'Ag', 'Zn'], '<p>The more negative the standard reduction potential, the stronger the metal as a reducing agent. E&deg; values: Li -3.05, Zn -0.76, Cu +0.34, Ag +0.80 V. Li is the most negative, so it gives up electrons most easily.</p>');
mk(1, 'electrolysis of molten salts', 'On electrolysis of molten NaCl with inert electrodes, the product at the cathode is', 'sodium metal', ['chlorine gas', 'hydrogen gas', 'sodium hydroxide'], '<p>No water is present, so the only cation, Na<sup>+</sup>, is reduced at the cathode: Na<sup>+</sup> + e<sup>-</sup> &rarr; Na. Chlorine forms at the anode.</p>');
nat(1, 'Faraday constant', 'How many coulombs of charge are carried by 0.5 mol of electrons? (F = 96500 C/mol)', 48250, 0, 'C', '<p>Q = n F = 0.5 &times; 96500 = <b>48250 C</b>.</p>', '', () => 0.5 * 96500);
mk(1, 'conductance and dilution', 'On diluting an aqueous solution of KCl, its conductivity (&kappa;) and molar conductivity (&Lambda;<sub>m</sub>) change as', '&kappa; decreases and &Lambda;<sub>m</sub> increases', ['&kappa; increases and &Lambda;<sub>m</sub> increases', '&kappa; decreases and &Lambda;<sub>m</sub> decreases', 'both stay the same'], '<p>Dilution puts fewer ions in each cm<sup>3</sup>, so &kappa; (conductance of a fixed volume) falls. But &Lambda;<sub>m</sub> = &kappa;/c: c falls faster than &kappa;, and ions interact less, so &Lambda;<sub>m</sub> rises.</p>');
mk(1, 'lead storage battery', 'The electrolyte used in a lead storage battery is', 'about 38 % H<sub>2</sub>SO<sub>4</sub> by mass', ['dilute HCl', 'a paste of NH<sub>4</sub>Cl and ZnCl<sub>2</sub>', 'concentrated KOH'], '<p>The lead storage battery has a Pb anode, a PbO<sub>2</sub> cathode and about 38 % sulphuric acid (density about 1.3 g/mL). The NH<sub>4</sub>Cl/ZnCl<sub>2</sub> paste belongs to the dry cell and KOH to the nickel-cadmium and alkaline cells.</p>');
mk(1, 'corrosion', 'Rusting of iron needs the presence of', 'both oxygen and water', ['oxygen only', 'water only', 'carbon dioxide only'], '<p>Rusting is an electrochemical process: water carries ions and oxygen is the oxidising agent (O<sub>2</sub> + 4H<sup>+</sup> + 4e<sup>-</sup> &rarr; 2H<sub>2</sub>O). Iron kept in dry air, or in boiled water sealed from air, does not rust.</p>');
mk(1, 'electrolytic cell', 'In an electrolytic cell the anode is', 'positive, and oxidation occurs there', ['negative, and oxidation occurs there', 'positive, and reduction occurs there', 'negative, and reduction occurs there'], '<p>An external battery pulls electrons out of the anode, so it is positive. Anions move to it and are oxidised. The cathode is negative and reduction occurs there.</p>', 'Anode is negative in galvanic cells but positive in electrolytic cells.');
mk(1, 'cell notation', 'In the cell notation Zn(s) | Zn<sup>2+</sup>(aq) || Cu<sup>2+</sup>(aq) | Cu(s), the double vertical line represents', 'the salt bridge', ['a phase boundary', 'the external wire', 'a porous cathode'], '<p>A single line | is a phase boundary (solid/solution). The double line || stands for the salt bridge (or porous partition) joining the two half-cells. By convention the anode is written on the left and the cathode on the right.</p>');
mk(1, 'fuel cells', 'In a hydrogen-oxygen fuel cell, the only product is', 'water', ['hydrogen peroxide', 'ammonia', 'carbon dioxide'], '<p>Overall: 2H<sub>2</sub> + O<sub>2</sub> &rarr; 2H<sub>2</sub>O. That is why such cells are called clean. The fuel is fed continuously from outside, which is the main difference from an ordinary battery.</p>');
mk(1, 'primary and secondary cells', 'Which of these is a primary (non-rechargeable) cell?', 'dry (Leclanch&eacute;) cell', ['lead storage battery', 'nickel-cadmium cell', 'lithium-ion cell'], '<p>In a primary cell the cell reaction cannot be reversed efficiently, so it is discarded after use. Lead storage, Ni-Cd and Li-ion cells are secondary: passing current backwards recharges them.</p>');
nat(1, 'conductivity', 'A conductivity cell has cell constant 1.25 cm<sup>-1</sup> and the solution in it shows a resistance of 50 &Omega;. Find the conductivity of the solution.', 0.025, 0.001, 'S cm<sup>-1</sup>', '<p>&kappa; = G*/R, where G* = l/A is the cell constant.</p><p>&kappa; = 1.25 / 50 = <b>0.025 S cm<sup>-1</sup></b>.</p>', '', () => 1.25 / 50);
// ---------- Level 2 ----------
nat(2, 'Nernst equation', 'Find the emf at 25 &deg;C of the cell Zn|Zn<sup>2+</sup>(0.01 M)||Cu<sup>2+</sup>(1 M)|Cu. E&deg;<sub>cell</sub> = 1.10 V. Use 2.303RT/F = 0.059 V.', 1.16, 0.01, 'V', '<p>Cell reaction: Zn + Cu<sup>2+</sup> &rarr; Zn<sup>2+</sup> + Cu, n = 2.</p><p>E = E&deg; - (0.059/2) log([Zn<sup>2+</sup>]/[Cu<sup>2+</sup>]) = 1.10 - 0.0295 log(0.01/1) = 1.10 + 0.059 = <b>1.159 &asymp; 1.16 V</b>.</p>', 'Lower product concentration raises emf.', () => 1.10 - 0.0295 * l10(0.01));
nat(2, 'Gibbs energy and emf', 'Calculate &Delta;G&deg; (in kJ) for the Daniell cell reaction, for which E&deg;<sub>cell</sub> = 1.10 V and n = 2. (F = 96500 C/mol)', -212.3, 0.5, 'kJ', '<p>&Delta;G&deg; = -nFE&deg; = -2 &times; 96500 &times; 1.10 = -212300 J = <b>-212.3 kJ</b>.</p>', 'Convert J to kJ.', () => -2 * 96500 * 1.10 / 1000);
nat(2, "Faraday's first law", 'A current of 2 A is passed for 4825 s through aqueous CuSO<sub>4</sub> with Pt electrodes. What mass of copper is deposited at the cathode? (Cu = 63.5)', 3.175, 0.01, 'g', '<p>Q = I t = 2 &times; 4825 = 9650 C = 0.1 F, so 0.1 mol of electrons.</p><p>Cu<sup>2+</sup> + 2e<sup>-</sup> &rarr; Cu needs 2 mol e<sup>-</sup> per mol Cu: n(Cu) = 0.05 mol.</p><p>Mass = 0.05 &times; 63.5 = <b>3.175 g</b>.</p>', '', () => 2 * 4825 / 96500 / 2 * 63.5);
nat(2, 'Kohlrausch law', 'The limiting molar conductivities (S cm<sup>2</sup> mol<sup>-1</sup>) are KCl 150, NaCl 126 and KNO<sub>3</sub> 145. Find &Lambda;&deg;<sub>m</sub> of sodium nitrate.', 121, 0, 'S cm<sup>2</sup> mol<sup>-1</sup>', '<p>By Kohlrausch law, &Lambda;&deg;(sodium nitrate) = &lambda;&deg;(Na<sup>+</sup>) + &lambda;&deg;(NO<sub>3</sub><sup>-</sup>) = [&Lambda;&deg;(NaCl) - &Lambda;&deg;(KCl)] + &Lambda;&deg;(KNO<sub>3</sub>)].</p><p>= 126 - 150 + 145 = <b>121</b>.</p>', '', () => 126 - 150 + 145);
nat(2, 'molar conductivity', 'A 0.10 M solution of an electrolyte has conductivity 0.012 S cm<sup>-1</sup>. Find its molar conductivity in S cm<sup>2</sup> mol<sup>-1</sup>.', 120, 0, 'S cm<sup>2</sup> mol<sup>-1</sup>', '<p>&Lambda;<sub>m</sub> = &kappa; &times; 1000 / c, with c in mol L<sup>-1</sup>.</p><p>= 0.012 &times; 1000 / 0.10 = <b>120</b>.</p>', 'The factor 1000 converts litres to cm<sup>3</sup>.', () => 0.012 * 1000 / 0.10);
mk(2, 'electrolysis of aqueous solutions', 'On electrolysing a concentrated aqueous solution of NaCl with inert electrodes, the products at cathode and anode are respectively', 'H<sub>2</sub> and Cl<sub>2</sub>', ['Na and Cl<sub>2</sub>', 'H<sub>2</sub> and O<sub>2</sub>', 'Na and O<sub>2</sub>'], '<p>At the cathode water is reduced more easily than Na<sup>+</sup> (E&deg; -2.71 V), giving H<sub>2</sub>. At the anode, Cl<sup>-</sup> is oxidised in preference to water because of the high overpotential for O<sub>2</sub> formation, so Cl<sub>2</sub> is released. NaOH is left in solution.</p>', 'In very dilute NaCl, oxygen appears at the anode.');
mk(2, 'electrolysis with active electrodes', 'Aqueous CuSO<sub>4</sub> is electrolysed with copper electrodes. Which statement is correct?', 'Copper dissolves at the anode and deposits at the cathode, so the solution stays the same colour', ['Oxygen is released at the anode and the blue colour fades', 'Hydrogen is released at the cathode', 'Copper deposits at both electrodes'], '<p>Copper is easier to oxidise than water or sulphate, so the Cu anode itself dissolves: Cu &rarr; Cu<sup>2+</sup> + 2e<sup>-</sup>. Cu<sup>2+</sup> deposits at the cathode. Copper lost at one electrode equals copper gained at the other, so [Cu<sup>2+</sup>] is unchanged. This is how copper is refined.</p>');
nat(2, 'equilibrium constant', 'For a cell reaction with n = 2 and E&deg;<sub>cell</sub> = 0.295 V at 298 K, find log K. Use 2.303RT/F = 0.059 V.', 10, 0, '', '<p>E&deg; = (0.059/n) log K, so log K = nE&deg;/0.059.</p><p>= 2 &times; 0.295 / 0.059 = <b>10</b> (K = 10<sup>10</sup>).</p>', '', () => 2 * 0.295 / 0.059);
mk(2, 'factors affecting cell emf', 'The emf of the cell Zn|Zn<sup>2+</sup>||Cu<sup>2+</sup>|Cu does NOT depend on', 'the size of the electrodes and the volume of solution', ['the concentration of Cu<sup>2+</sup>', 'the temperature', 'the concentration of Zn<sup>2+</sup>'], '<p>The Nernst equation shows E depends on temperature, on the nature of the electrodes and on ion concentrations (activities). Emf is an intensive property: electrode area and amount of solution change the current a cell can supply, not its emf.</p>');
mk(2, 'Kohlrausch law', 'Kohlrausch law of independent migration of ions states that', 'the limiting molar conductivity of an electrolyte is the sum of the limiting molar conductivities of its cation and anion', ['molar conductivity is always independent of concentration', 'the conductivity of a solution is the same for all electrolytes', 'ions of the same charge always have equal conductivity'], '<p>At infinite dilution each ion moves independently, so &Lambda;&deg;<sub>m</sub> = &nu;<sub>+</sub>&lambda;&deg;<sub>+</sub> + &nu;<sub>-</sub>&lambda;&deg;<sub>-</sub>. It does not say &Lambda;<sub>m</sub> is constant at finite concentration.</p>');
mk(2, 'strong electrolyte conductance', 'For a strong electrolyte, a plot of &Lambda;<sub>m</sub> against &radic;c is', 'a straight line with negative slope, whose intercept on the y-axis is &Lambda;&deg;<sub>m</sub>', ['a straight line with positive slope through the origin', 'a curve that rises steeply near zero concentration', 'a horizontal line'], '<p>Debye-H&uuml;ckel-Onsager: &Lambda;<sub>m</sub> = &Lambda;&deg;<sub>m</sub> - A&radic;c. So the graph is linear with intercept &Lambda;&deg;<sub>m</sub> and slope -A. A curve that rises steeply near zero concentration is how a <i>weak</i> electrolyte behaves.</p>');
mk(2, 'displacement', 'Which metal will NOT displace copper from aqueous CuSO<sub>4</sub>? (E&deg; of Cu<sup>2+</sup>/Cu = +0.34 V)', 'Ag (E&deg; = +0.80 V)', ['Zn (E&deg; = -0.76 V)', 'Fe (E&deg; = -0.44 V)', 'Mg (E&deg; = -2.37 V)'], '<p>A metal displaces Cu<sup>2+</sup> only if it is a better reducing agent, i.e. its E&deg; is lower than +0.34 V. Zn, Fe and Mg qualify. Ag has a higher E&deg;, so the reaction Ag + Cu<sup>2+</sup> &rarr; Ag<sup>+</sup> + Cu is non-spontaneous (E&deg;cell = -0.46 V).</p>');
nat(2, "Faraday's laws", 'How long (in seconds) must a current of 0.5 A flow to deposit 1.08 g of silver from AgNO<sub>3</sub>? (Ag = 108, F = 96500)', 1930, 0, 's', '<p>n(Ag) = 1.08/108 = 0.01 mol; Ag<sup>+</sup> + e<sup>-</sup> &rarr; Ag, so 0.01 mol e<sup>-</sup>.</p><p>Q = 0.01 &times; 96500 = 965 C; t = Q/I = 965/0.5 = <b>1930 s</b>.</p>', '', () => 0.01 * 96500 / 0.5);
mk(2, 'electrons in half reactions', 'The number of faradays needed to reduce 1 mol of MnO<sub>4</sub><sup>-</sup> to Mn<sup>2+</sup> in acidic medium is', '5', ['1', '3', '7'], '<p>MnO<sub>4</sub><sup>-</sup> + 8H<sup>+</sup> + 5e<sup>-</sup> &rarr; Mn<sup>2+</sup> + 4H<sub>2</sub>O. Mn goes from +7 to +2, so 5 electrons per MnO<sub>4</sub><sup>-</sup>, i.e. 5 F. (3 would reduce it to MnO<sub>2</sub>.)</p>');
nat(2, 'degree of dissociation', 'The molar conductivity of 0.1 M acetic acid is 39 S cm<sup>2</sup> mol<sup>-1</sup> and &Lambda;&deg;<sub>m</sub> = 390. Find the degree of dissociation &alpha;.', 0.1, 0.002, '', '<p>For a weak electrolyte &alpha; = &Lambda;<sub>m</sub>/&Lambda;&deg;<sub>m</sub> = 39/390 = <b>0.10</b>.</p>', '', () => 39 / 390);
mk(2, 'dry cell', 'In the dry (Leclanch&eacute;) cell, the anode and the cathode are respectively', 'zinc container and graphite rod surrounded by MnO<sub>2</sub> and carbon', ['graphite rod and zinc container', 'lead and lead dioxide', 'cadmium and nickel oxide-hydroxide'], '<p>The zinc can is the anode (Zn &rarr; Zn<sup>2+</sup> + 2e<sup>-</sup>). The graphite rod, packed in MnO<sub>2</sub> and carbon, is the cathode where MnO<sub>2</sub> is reduced. NH<sub>4</sub>Cl and ZnCl<sub>2</sub> paste is the electrolyte. Option 3 is the lead storage battery; option 4 is the Ni-Cd cell.</p>');
nat(2, 'equivalent conductivity', 'A 0.5 N solution has conductivity 0.01 S cm<sup>-1</sup>. Find its equivalent conductivity in S cm<sup>2</sup> eq<sup>-1</sup>.', 20, 0, 'S cm<sup>2</sup> eq<sup>-1</sup>', '<p>&Lambda;<sub>eq</sub> = &kappa; &times; 1000 / N = 0.01 &times; 1000 / 0.5 = <b>20</b>.</p>', 'Use normality, not molarity.', () => 0.01 * 1000 / 0.5);
nat(2, 'single electrode potential', 'Calculate the reduction potential of an Ag<sup>+</sup>/Ag electrode dipping in 0.01 M AgNO<sub>3</sub> at 25 &deg;C. E&deg; = +0.80 V.', 0.68, 0.01, 'V', '<p>Ag<sup>+</sup> + e<sup>-</sup> &rarr; Ag, n = 1: E = E&deg; - 0.059 log(1/[Ag<sup>+</sup>]) = 0.80 + 0.059 log 0.01.</p><p>= 0.80 - 0.118 = <b>0.682 V</b>.</p>', 'Lower [Ag<sup>+</sup>] makes the electrode less oxidising.', () => 0.80 + 0.059 * l10(0.01));
mk(2, 'cell constant', 'The unit of cell constant (l/A) of a conductivity cell is', 'cm<sup>-1</sup>', ['cm', 'S cm<sup>-1</sup>', 'ohm'], '<p>Cell constant G* = l/A: length between electrodes over their area, so cm/cm<sup>2</sup> = cm<sup>-1</sup>. It is found by measuring the resistance with a solution of known &kappa;, usually KCl.</p>');
mk(2, 'corrosion protection', 'Which method protects an iron pipe by making it the cathode of a cell?', 'attaching a block of magnesium (sacrificial anode)', ['coating it with a layer of tin', 'painting it with a layer of grease', 'attaching a block of copper'], '<p>Mg is more reactive than Fe, so it corrodes instead and iron receives electrons (cathodic protection). Tin only gives a barrier: once scratched, iron is the anode and rusts faster. Grease is only a barrier. Copper would make iron the anode.</p>');
nat(2, 'standard emf', 'Find E&deg;<sub>cell</sub> for Cu|Cu<sup>2+</sup>||Ag<sup>+</sup>|Ag. E&deg;(Cu<sup>2+</sup>/Cu) = +0.34 V, E&deg;(Ag<sup>+</sup>/Ag) = +0.80 V.', 0.46, 0.01, 'V', '<p>E&deg;<sub>cell</sub> = E&deg;(cathode) - E&deg;(anode) = 0.80 - 0.34 = <b>0.46 V</b>. Do not multiply E&deg;(Ag) by 2 when balancing the reaction: E&deg; is intensive.</p>', '', () => 0.80 - 0.34);
mk(2, 'effect of temperature', 'When the temperature of an electrolytic solution rises, its conductance', 'increases, because ions move faster and the solution becomes less viscous', ['decreases, as in metals', 'stays the same', 'first decreases and then becomes zero'], '<p>In metals, resistance rises with temperature because atoms vibrate more. In electrolytes the charge carriers are ions: heat lowers the viscosity of the solvent and cuts solvation, so ions move faster and conductance rises.</p>');
mk(2, 'concentration cell', 'In the concentration cell Zn|Zn<sup>2+</sup>(c<sub>1</sub>)||Zn<sup>2+</sup>(c<sub>2</sub>)|Zn, the emf is positive as written when', 'c<sub>2</sub> &gt; c<sub>1</sub>', ['c<sub>2</sub> &lt; c<sub>1</sub>', 'c<sub>1</sub> = c<sub>2</sub>', 'c<sub>2</sub> = 0 only'], '<p>E = (0.059/2) log(c<sub>2</sub>/c<sub>1</sub>) (right electrode is the cathode, E&deg; = 0). It is positive when c<sub>2</sub> &gt; c<sub>1</sub>: the more concentrated solution is reduced, the dilute side is oxidised. At c<sub>1</sub> = c<sub>2</sub> the emf is zero.</p>');
nat(2, 'charge for deposition', 'Find the charge in coulombs needed to deposit 1 mol of aluminium from molten Al<sub>2</sub>O<sub>3</sub> (Al<sup>3+</sup> + 3e<sup>-</sup> &rarr; Al). F = 96500 C/mol.', 289500, 0, 'C', '<p>3 mol of electrons per mole of Al: Q = 3 &times; 96500 = <b>289500 C</b>.</p>', '', () => 3 * 96500);
mk(2, 'strongest oxidising agent', 'From the E&deg; values F<sub>2</sub> +2.87, Cl<sub>2</sub> +1.36, Br<sub>2</sub> +1.09 and I<sub>2</sub> +0.54 V, which reaction is spontaneous?', 'Cl<sub>2</sub> + 2Br<sup>-</sup> &rarr; 2Cl<sup>-</sup> + Br<sub>2</sub>', ['Br<sub>2</sub> + 2Cl<sup>-</sup> &rarr; 2Br<sup>-</sup> + Cl<sub>2</sub>', 'I<sub>2</sub> + 2Br<sup>-</sup> &rarr; 2I<sup>-</sup> + Br<sub>2</sub>', 'I<sub>2</sub> + 2F<sup>-</sup> &rarr; 2I<sup>-</sup> + F<sub>2</sub>'], '<p>A halogen oxidises the halide ions of a halogen lower in the table. Cl<sub>2</sub> (1.36) oxidises Br<sup>-</sup>: E&deg;cell = 1.36 - 1.09 = +0.27 V, spontaneous. The other three have negative E&deg;cell.</p>');
mk(2, 'hydrogen electrode', 'For the half-cell Pt | H<sub>2</sub>(1 bar) | H<sup>+</sup>(aq), the potential at 25 &deg;C is given by', '-0.059 &times; pH volt', ['+0.059 &times; pH volt', '-0.059 &times; pOH volt', '0.059 &times; [H<sup>+</sup>] volt'], '<p>Reduction 2H<sup>+</sup> + 2e<sup>-</sup> &rarr; H<sub>2</sub>: E = 0 - (0.059/2) log(1/[H<sup>+</sup>]<sup>2</sup>) = 0.059 log [H<sup>+</sup>] = -0.059 pH.</p>');
// ---------- Level 3 ----------
nat(3, 'Nernst equation', 'Find the emf at 25 &deg;C of Zn|Zn<sup>2+</sup>(0.1 M)||Cu<sup>2+</sup>(0.001 M)|Cu. E&deg;<sub>cell</sub> = 1.10 V; 2.303RT/F = 0.059 V.', 1.04, 0.01, 'V', '<p>E = E&deg; - (0.059/2) log([Zn<sup>2+</sup>]/[Cu<sup>2+</sup>]) = 1.10 - 0.0295 log(0.1/0.001) = 1.10 - 0.0295 &times; 2.</p><p>= 1.10 - 0.059 = <b>1.041 V</b>.</p>', 'Q has product concentration on top: Zn<sup>2+</sup>/Cu<sup>2+</sup>.', () => 1.10 - 0.0295 * l10(100));
nat(3, 'concentration cell', 'Find the emf at 25 &deg;C of Cu|Cu<sup>2+</sup>(0.01 M)||Cu<sup>2+</sup>(1.0 M)|Cu. Use 2.303RT/F = 0.059 V.', 0.059, 0.002, 'V', '<p>Same metal at both electrodes, so E&deg; = 0 and E = (0.059/2) log(c<sub>cathode</sub>/c<sub>anode</sub>).</p><p>= 0.0295 &times; log(1.0/0.01) = 0.0295 &times; 2 = <b>0.059 V</b>.</p>', '', () => 0.0295 * 2);
nat(3, 'pH from cell emf', 'A hydrogen electrode (1 bar H<sub>2</sub>) dipped in a solution of unknown pH is joined to a standard hydrogen electrode. The emf measured is 0.236 V with the unknown electrode as the negative pole. Find the pH. (2.303RT/F = 0.059 V)', 4, 0, '', '<p>The unknown electrode has E = -0.059 pH, the SHE is 0 V, so emf = 0.059 pH.</p><p>pH = 0.236/0.059 = <b>4</b>.</p>', '', () => 0.236 / 0.059);
nat(3, 'pH from cell emf', 'The cell Zn|Zn<sup>2+</sup>(1 M)||H<sup>+</sup>(x M)|H<sub>2</sub>(1 bar), Pt has emf 0.465 V at 25 &deg;C. E&deg;(Zn<sup>2+</sup>/Zn) = -0.76 V. Find the pH of the hydrogen half-cell. (0.059 V)', 5, 0, '', '<p>Zn + 2H<sup>+</sup> &rarr; Zn<sup>2+</sup> + H<sub>2</sub>, n = 2, E&deg; = 0.76 V.</p><p>E = 0.76 - 0.0295 log(1/[H<sup>+</sup>]<sup>2</sup>) = 0.76 - 0.059 pH.</p><p>0.465 = 0.76 - 0.059 pH &rArr; pH = 0.295/0.059 = <b>5</b>.</p>', '', () => (0.76 - 0.465) / 0.059);
nat(3, 'equilibrium constant', 'Find log<sub>10</sub>K at 25 &deg;C for Cu + 2Ag<sup>+</sup> &rarr; Cu<sup>2+</sup> + 2Ag, given E&deg;(Ag<sup>+</sup>/Ag) = 0.80 V, E&deg;(Cu<sup>2+</sup>/Cu) = 0.34 V.', 15.59, 0.05, '', '<p>E&deg;cell = 0.80 - 0.34 = 0.46 V, n = 2.</p><p>log K = nE&deg;/0.059 = 2 &times; 0.46/0.059 = <b>15.59</b>.</p>', '', () => 2 * 0.46 / 0.059);
nat(3, 'Ksp from cells', 'E&deg; for Ag<sup>+</sup> + e<sup>-</sup> &rarr; Ag is 0.80 V and for AgCl + e<sup>-</sup> &rarr; Ag + Cl<sup>-</sup> is 0.22 V. Find pK<sub>sp</sub> of AgCl (0.059 V).', 9.83, 0.05, '', '<p>AgCl(s) &rarr; Ag<sup>+</sup> + Cl<sup>-</sup> is the second half-reaction run backwards plus the first: the cell has cathode Ag<sup>+</sup>/Ag (0.80) and anode Ag/AgCl (0.22), E&deg; = 0.58 V for Ag<sup>+</sup> + Cl<sup>-</sup> &rarr; AgCl.</p><p>log(1/K<sub>sp</sub>) = 0.58/0.059 = 9.83, so pK<sub>sp</sub> = <b>9.83</b> (K<sub>sp</sub> &asymp; 1.5 &times; 10<sup>-10</sup>).</p>', 'Ksp is the reverse of the formation reaction.', () => 0.58 / 0.059);
nat(3, "Faraday's laws in series", 'The same current passes through two cells in series, one with AgNO<sub>3</sub> and one with CuSO<sub>4</sub>. If 1.08 g of Ag is deposited, what mass of Cu is deposited? (Ag = 108, Cu = 63.5)', 0.3175, 0.002, 'g', '<p>Same charge in both cells. 1.08 g Ag = 0.01 mol, so 0.01 mol e<sup>-</sup> flowed.</p><p>Cu needs 2 e<sup>-</sup>: 0.005 mol &times; 63.5 = <b>0.3175 g</b>.</p>', '', () => 0.005 * 63.5);
nat(3, 'electrolysis of water', 'What volume of H<sub>2</sub> at STP (22.4 L/mol) is released at the cathode when 1930 C of charge passes through acidified water?', 224, 0, 'mL', '<p>1930 C / 96500 = 0.02 mol e<sup>-</sup>. 2H<sup>+</sup> + 2e<sup>-</sup> &rarr; H<sub>2</sub> gives 0.01 mol H<sub>2</sub>.</p><p>V = 0.01 &times; 22400 = <b>224 mL</b>.</p>', '', () => 1930 / 96500 / 2 * 22400);
nat(3, 'current efficiency', 'A current of 2 A is passed for 1 hour through CuSO<sub>4</sub> solution and 2.00 g of copper is actually collected. What is the current efficiency in %? (Cu = 63.5, F = 96500)', 84.4, 0.3, '%', '<p>Theoretical mass = (I t / 2F) &times; 63.5 = (7200/193000) &times; 63.5 = 2.369 g.</p><p>Efficiency = 2.00/2.369 &times; 100 = <b>84.4 %</b>.</p>', 'Use n = 2 for Cu.', () => 2.0 / (7200 / 193000 * 63.5) * 100);
nat(3, 'Ksp from conductance', 'A saturated solution of AgCl has conductivity 1.383 &times; 10<sup>-6</sup> S cm<sup>-1</sup> (water correction already made). &Lambda;&deg;<sub>m</sub>(AgCl) = 138.3 S cm<sup>2</sup> mol<sup>-1</sup>. Find K<sub>sp</sub> in units of 10<sup>-10</sup>.', 1.0, 0.02, '&times; 10<sup>-10</sup>', '<p>The solution is so dilute that &Lambda;<sub>m</sub> &asymp; &Lambda;&deg;<sub>m</sub>. Solubility s = &kappa; &times; 1000/&Lambda;&deg;<sub>m</sub> = 1.383 &times; 10<sup>-6</sup> &times; 1000/138.3 = 1.0 &times; 10<sup>-5</sup> mol/L.</p><p>K<sub>sp</sub> = s<sup>2</sup> = 1.0 &times; 10<sup>-10</sup> &rArr; <b>1.0</b>.</p>', 'Remember the 1000 and to subtract the conductivity of water.', () => (1.383e-6 * 1000 / 138.3) ** 2 / 1e-10);
nat(3, 'weak electrolyte', 'A 0.01 M weak monoprotic acid has &Lambda;<sub>m</sub> = 40.7 S cm<sup>2</sup> mol<sup>-1</sup>; &Lambda;&deg;<sub>m</sub> = 407. Find K<sub>a</sub> in units of 10<sup>-5</sup>.', 11.1, 0.15, '&times; 10<sup>-5</sup>', '<p>&alpha; = 40.7/407 = 0.1.</p><p>K<sub>a</sub> = C&alpha;<sup>2</sup>/(1 - &alpha;) = 0.01 &times; 0.01/0.9 = 1.11 &times; 10<sup>-4</sup> = <b>11.1 &times; 10<sup>-5</sup></b>.</p>', 'Do not drop (1 - &alpha;) when &alpha; = 0.1.', () => 0.01 * 0.01 / 0.9 / 1e-5);
nat(3, 'cell constant', 'A cell filled with 0.1 M KCl (&kappa; = 0.0129 S cm<sup>-1</sup>) shows a resistance of 200 &Omega;. Filled with 0.05 M weak acid, the same cell shows 516 &Omega;. Find the molar conductivity of the acid in S cm<sup>2</sup> mol<sup>-1</sup>.', 100, 0, 'S cm<sup>2</sup> mol<sup>-1</sup>', '<p>Cell constant G* = &kappa;R = 0.0129 &times; 200 = 2.58 cm<sup>-1</sup>.</p><p>&kappa;(acid) = G*/R = 2.58/516 = 0.005 S cm<sup>-1</sup>.</p><p>&Lambda;<sub>m</sub> = 0.005 &times; 1000/0.05 = <b>100</b>.</p>', '', () => 0.005 * 1000 / 0.05);
nat(3, 'Kohlrausch law for weak electrolytes', 'The &Lambda;&deg;<sub>m</sub> values (S cm<sup>2</sup> mol<sup>-1</sup>) are CH<sub>3</sub>COONa 91, HCl 426 and NaCl 126. Find &Lambda;&deg;<sub>m</sub> of CH<sub>3</sub>COOH.', 391, 0, 'S cm<sup>2</sup> mol<sup>-1</sup>', '<p>CH<sub>3</sub>COOH = CH<sub>3</sub>COONa + HCl - NaCl (Na<sup>+</sup> and Cl<sup>-</sup> cancel).</p><p>= 91 + 426 - 126 = <b>391</b>.</p>', 'Weak electrolytes cannot be extrapolated; this is the only way.', () => 91 + 426 - 126);
nat(3, 'half cell Nernst', 'Find the potential of a Pt electrode in a solution with [Fe<sup>3+</sup>] = 1 M and [Fe<sup>2+</sup>] = 0.01 M. E&deg;(Fe<sup>3+</sup>/Fe<sup>2+</sup>) = 0.77 V; 0.059 V.', 0.89, 0.01, 'V', '<p>Fe<sup>3+</sup> + e<sup>-</sup> &rarr; Fe<sup>2+</sup>, n = 1: E = 0.77 - 0.059 log([Fe<sup>2+</sup>]/[Fe<sup>3+</sup>]) = 0.77 - 0.059 log(0.01) = 0.77 + 0.118 = <b>0.888 V</b>.</p>', '', () => 0.77 - 0.059 * l10(0.01));
nat(3, 'electrolysis of molten oxide', 'A current of 3.86 A passes for 1000 s through molten Al<sub>2</sub>O<sub>3</sub>. What mass of aluminium is deposited? (Al = 27, F = 96500)', 0.36, 0.005, 'g', '<p>Q = 3.86 &times; 1000 = 3860 C = 0.04 mol e<sup>-</sup>.</p><p>n(Al) = 0.04/3 mol; mass = 0.04/3 &times; 27 = <b>0.36 g</b>.</p>', '', () => 3860 / 96500 / 3 * 27);
nat(3, 'cells in series', 'The same current flows through a cell with AgNO<sub>3</sub> and a cell with dilute H<sub>2</sub>SO<sub>4</sub> (Pt electrodes). 5.4 g of Ag is deposited. Find the volume of H<sub>2</sub> at STP in mL (Ag = 108).', 560, 0, 'mL', '<p>n(Ag) = 5.4/108 = 0.05 mol, so 0.05 mol e<sup>-</sup> passed.</p><p>H<sub>2</sub> = 0.025 mol, V = 0.025 &times; 22400 = <b>560 mL</b>.</p>', '', () => 5.4 / 108 / 2 * 22400);
mk(3, 'ionic mobility', 'Which cation has the highest limiting molar ionic conductivity in water at 25 &deg;C?', 'H<sup>+</sup>, because protons hop along hydrogen-bonded water molecules', ['Li<sup>+</sup>, because it is the smallest alkali metal ion', 'K<sup>+</sup>, because it is the biggest alkali metal ion', 'Cs<sup>+</sup>, because it is the most heavily hydrated'], '<p>H<sup>+</sup> (about 350 S cm<sup>2</sup> mol<sup>-1</sup>) moves by the Grotthuss mechanism: a proton jumps from H<sub>3</sub>O<sup>+</sup> to the next water. Among alkali ions the smaller ion is more heavily hydrated and slower: Li<sup>+</sup> is the slowest and Cs<sup>+</sup> the fastest of the group.</p>', 'Small ion does not mean fast ion in water.');
mk(3, 'conductance of weak electrolytes', 'When a weak acid solution is diluted, which of the following does NOT increase?', 'conductivity &kappa;', ['degree of dissociation', 'molar conductivity', 'number of moles of ions in the solution'], '<p>On dilution, &alpha; rises (Ostwald), &Lambda;<sub>m</sub> rises, and the total moles of ions in the solution rise. But the concentration of ions per unit volume falls, so &kappa; falls overall.</p>', 'The words "NOT increase" are the trap.');
mk(3, 'electrolysis of aqueous solutions', 'Electrolysis of aqueous Na<sub>2</sub>SO<sub>4</sub> with platinum electrodes gives', 'H<sub>2</sub> at the cathode and O<sub>2</sub> at the anode', ['Na at the cathode and SO<sub>2</sub> at the anode', 'Na at the cathode and O<sub>2</sub> at the anode', 'H<sub>2</sub> at the cathode and S<sub>2</sub>O<sub>8</sub><sup>2-</sup> at the anode'], '<p>Na<sup>+</sup> (-2.71 V) is much harder to reduce than water, and SO<sub>4</sub><sup>2-</sup> is already in its highest state, so water is electrolysed: 2H<sub>2</sub>O + 2e<sup>-</sup> &rarr; H<sub>2</sub> + 2OH<sup>-</sup> and 2H<sub>2</sub>O &rarr; O<sub>2</sub> + 4H<sup>+</sup> + 4e<sup>-</sup>. Volume ratio H<sub>2</sub>:O<sub>2</sub> = 2:1.</p>');
mk(3, 'electrode potential and stoichiometry', 'The standard reduction potential of Ag<sup>+</sup>/Ag is +0.80 V. For 2Ag<sup>+</sup> + 2e<sup>-</sup> &rarr; 2Ag, E&deg; is', '+0.80 V', ['+1.60 V', '+0.40 V', '+0.64 V'], '<p>E&deg; is an intensive property: it does not change when the equation is multiplied. &Delta;G&deg; doubles (n doubles) but E&deg; = -&Delta;G&deg;/nF stays at 0.80 V.</p>', 'Famous trap: multiplying E&deg; by the coefficient.');
mk(3, 'combining half cells', 'Given Fe<sup>3+</sup> + e<sup>-</sup> &rarr; Fe<sup>2+</sup>, E&deg; = +0.77 V and Fe<sup>2+</sup> + 2e<sup>-</sup> &rarr; Fe, E&deg; = -0.44 V, the E&deg; of Fe<sup>3+</sup> + 3e<sup>-</sup> &rarr; Fe is about', '-0.04 V', ['+0.33 V', '+0.165 V', '-1.21 V'], '<p>E&deg; values cannot be added directly, but &Delta;G&deg; can. &Delta;G&deg;<sub>1</sub> = -1 &times; F &times; 0.77, &Delta;G&deg;<sub>2</sub> = -2 &times; F &times; (-0.44).</p><p>Sum = -F(0.77 - 0.88) = +0.11 F = -3F E&deg;, so E&deg; = (0.77 + 2(-0.44))/3 = -0.11/3 = <b>-0.037 V</b>.</p>', 'Weighted by n, not a plain sum or average.');
mk(3, 'galvanic cell at equilibrium', 'A Daniell cell is allowed to discharge fully until it stops. At that point', 'E<sub>cell</sub> = 0 and Q = K', ['E<sub>cell</sub> = E&deg;cell and Q = 1', 'E&deg;<sub>cell</sub> = 0 and Q = K', 'E<sub>cell</sub> = 0 and Q = 1'], '<p>At equilibrium the reaction has no driving force: &Delta;G = 0, so E = 0. The Nernst equation then gives 0 = E&deg; - (0.059/n) log K, i.e. Q = K. E&deg; itself never changes (it depends only on the cell and temperature).</p>');
mk(3, 'electrolysis of aqueous salts', 'Aqueous CuCl<sub>2</sub> is electrolysed with platinum electrodes. The products at cathode and anode are', 'Cu and Cl<sub>2</sub>', ['H<sub>2</sub> and Cl<sub>2</sub>', 'Cu and O<sub>2</sub>', 'H<sub>2</sub> and O<sub>2</sub>'], '<p>Cu<sup>2+</sup> (E&deg; +0.34 V) is reduced far more easily than water, so copper metal forms at the cathode. At the anode Cl<sup>-</sup> is oxidised to Cl<sub>2</sub> (kinetically preferred over water).</p>');
mk(3, 'corrosion', 'A scratched tin-plated iron can and a scratched galvanised (zinc-coated) iron sheet are left in moist air. Which statement is correct?', 'Iron in the tin-plated can rusts faster; iron in the galvanised sheet is protected', ['Iron rusts faster in both', 'Iron is protected in both', 'Iron in the tin-plated can is protected; iron in the galvanised sheet rusts faster'], '<p>Tin (E&deg; -0.14 V) is less active than iron (-0.44 V), so at the scratch iron becomes the anode and rusts quickly. Zinc (-0.76 V) is more active than iron, so zinc acts as the anode and iron stays the cathode and is protected even when scratched.</p>');
mk(3, 'lead storage battery', 'During discharge of a lead storage battery', 'H<sub>2</sub>SO<sub>4</sub> is consumed, water is formed and PbSO<sub>4</sub> forms on both electrodes', ['H<sub>2</sub>SO<sub>4</sub> is formed and PbSO<sub>4</sub> forms on one electrode only', 'only Pb is oxidised and no solid forms at the cathode', 'the electrolyte becomes denser as Pb<sup>2+</sup> dissolves'], '<p>Anode: Pb + SO<sub>4</sub><sup>2-</sup> &rarr; PbSO<sub>4</sub> + 2e<sup>-</sup>. Cathode: PbO<sub>2</sub> + SO<sub>4</sub><sup>2-</sup> + 4H<sup>+</sup> + 2e<sup>-</sup> &rarr; PbSO<sub>4</sub> + 2H<sub>2</sub>O. Overall: Pb + PbO<sub>2</sub> + 2H<sub>2</sub>SO<sub>4</sub> &rarr; 2PbSO<sub>4</sub> + 2H<sub>2</sub>O. The acid gets used up, so density falls: this is how a battery state is tested.</p>');
mk(3, 'mercury cell', 'The emf of the mercury cell stays constant (about 1.35 V) during use because', 'the net cell reaction involves no ion whose concentration changes in the electrolyte', ['it is a rechargeable cell', 'mercury has a very high conductivity', 'it contains a salt bridge'], '<p>The mercury cell reaction is Zn(Hg) + HgO &rarr; ZnO + Hg. OH<sup>-</sup> in the KOH/ZnO paste appears on both sides, so no concentration changes and the emf stays steady. That makes it ideal for watches and hearing aids.</p>');
mk(3, 'fuel cell', 'In an alkaline H<sub>2</sub>-O<sub>2</sub> fuel cell, the reaction at the anode is', 'H<sub>2</sub> + 2OH<sup>-</sup> &rarr; 2H<sub>2</sub>O + 2e<sup>-</sup>', ['O<sub>2</sub> + 2H<sub>2</sub>O + 4e<sup>-</sup> &rarr; 4OH<sup>-</sup>', '2H<sup>+</sup> + 2e<sup>-</sup> &rarr; H<sub>2</sub>', '2H<sub>2</sub>O &rarr; O<sub>2</sub> + 4H<sup>+</sup> + 4e<sup>-</sup>'], '<p>Hydrogen is the fuel and is oxidised at the anode: H<sub>2</sub> + 2OH<sup>-</sup> &rarr; 2H<sub>2</sub>O + 2e<sup>-</sup>. Option 1 is the cathode reaction. Options 3 and 4 are not what the cell does.</p>');
mk(3, 'equivalent conductivity', 'For Al<sub>2</sub>(SO<sub>4</sub>)<sub>3</sub>, the relation between molar conductivity and equivalent conductivity at the same concentration is', '&Lambda;<sub>eq</sub> = &Lambda;<sub>m</sub>/6', ['&Lambda;<sub>eq</sub> = 6&Lambda;<sub>m</sub>', '&Lambda;<sub>eq</sub> = &Lambda;<sub>m</sub>/3', '&Lambda;<sub>eq</sub> = &Lambda;<sub>m</sub>/5'], '<p>One mole of Al<sub>2</sub>(SO<sub>4</sub>)<sub>3</sub> carries a total charge of 6 on each ion type (2 Al<sup>3+</sup>), so it holds 6 equivalents. Normality = 6 &times; molarity, hence &Lambda;<sub>eq</sub> = &Lambda;<sub>m</sub>/6.</p>');
// ---------- Level 4 ----------
nat(4, 'Nernst equation', 'Find the emf at 25 &deg;C of Ni|Ni<sup>2+</sup>(0.01 M)||Ag<sup>+</sup>(0.1 M)|Ag. E&deg;(Ni<sup>2+</sup>/Ni) = -0.25 V, E&deg;(Ag<sup>+</sup>/Ag) = +0.80 V. Use 0.059 V.', 1.05, 0.01, 'V', '<p>Cell reaction: Ni + 2Ag<sup>+</sup> &rarr; Ni<sup>2+</sup> + 2Ag, n = 2. E&deg; = 0.80 + 0.25 = 1.05 V.</p><p>Q = [Ni<sup>2+</sup>]/[Ag<sup>+</sup>]<sup>2</sup> = 0.01/(0.1)<sup>2</sup> = 1, so log Q = 0 and E = E&deg; = <b>1.05 V</b>.</p>', 'The silver concentration is squared in Q.', () => 1.05 - 0.0295 * l10(0.01 / 0.01));
nat(4, 'equilibrium constant', 'Find log K at 298 K for Zn + Cu<sup>2+</sup> &rarr; Zn<sup>2+</sup> + Cu (E&deg;cell = 1.10 V). Use 0.059 V.', 37.3, 0.1, '', '<p>log K = nE&deg;/0.059 = 2 &times; 1.10/0.059 = <b>37.3</b>. So [Zn<sup>2+</sup>]/[Cu<sup>2+</sup>] reaches about 10<sup>37</sup> at equilibrium: the reaction goes essentially to completion.</p>', '', () => 2 * 1.10 / 0.059);
nat(4, 'Nernst equation with solubility', 'Find the emf at 25 &deg;C of Ag|AgCl(s), Cl<sup>-</sup>(0.1 M) || Ag<sup>+</sup>(0.1 M)|Ag. K<sub>sp</sub>(AgCl) = 1.8 &times; 10<sup>-10</sup>. Use 0.059 V.', 0.457, 0.005, 'V', '<p>Both electrodes are silver, so it is a concentration cell in Ag<sup>+</sup>.</p><p>Left: [Ag<sup>+</sup>] = K<sub>sp</sub>/[Cl<sup>-</sup>] = 1.8 &times; 10<sup>-10</sup>/0.1 = 1.8 &times; 10<sup>-9</sup> M. Right: 0.1 M.</p><p>E = 0.059 log(0.1/1.8 &times; 10<sup>-9</sup>) = 0.059 &times; 7.745 = <b>0.457 V</b>.</p>', 'n = 1 for silver.', () => 0.059 * l10(0.1 / 1.8e-9));
nat(4, 'electrolysis and pH', '0.5 L of 0.20 M CuSO<sub>4</sub> is electrolysed with Pt electrodes using 5 A for 1930 s. Assuming the volume is constant and no gas escapes unaccounted, find the pH of the final solution. (Neglect the initial pH.)', 0.70, 0.02, '', '<p>Q = 5 &times; 1930 = 9650 C = 0.1 mol e<sup>-</sup>.</p><p>Cathode: Cu<sup>2+</sup> + 2e<sup>-</sup> &rarr; Cu (0.05 mol Cu used, so 0.05 mol Cu<sup>2+</sup> remains). Anode: 2H<sub>2</sub>O &rarr; O<sub>2</sub> + 4H<sup>+</sup> + 4e<sup>-</sup>: 0.1 mol e<sup>-</sup> gives 0.1 mol H<sup>+</sup>.</p><p>[H<sup>+</sup>] = 0.1/0.5 = 0.2 M, pH = -log 0.2 = <b>0.70</b>.</p>', 'Each electron releases one H<sup>+</sup> at the anode.', () => -l10(0.1 / 0.5));
nat(4, 'electrolysis of brine', 'Brine is electrolysed with inert electrodes. When 1 F of charge has passed, what total volume (in litres, at STP) of H<sub>2</sub> and Cl<sub>2</sub> together is released? (22.4 L/mol)', 22.4, 0.1, 'L', '<p>1 F = 1 mol e<sup>-</sup>. Cathode: H<sub>2</sub>O + e<sup>-</sup> &rarr; &frac12;H<sub>2</sub> + OH<sup>-</sup> gives 0.5 mol H<sub>2</sub>. Anode: Cl<sup>-</sup> &rarr; &frac12;Cl<sub>2</sub> + e<sup>-</sup> gives 0.5 mol Cl<sub>2</sub>.</p><p>Total = 1 mol &times; 22.4 = <b>22.4 L</b>.</p>', '', () => 22.4);
nat(4, 'Ksp from conductance', 'Saturated BaSO<sub>4</sub> has conductivity 4.1 &times; 10<sup>-6</sup> S cm<sup>-1</sup>; the water used has 1.5 &times; 10<sup>-6</sup> S cm<sup>-1</sup>. Take &Lambda;&deg;<sub>m</sub>(BaSO<sub>4</sub>) = 286 S cm<sup>2</sup> mol<sup>-1</sup>. Find K<sub>sp</sub> in units of 10<sup>-11</sup>.', 8.26, 0.1, '&times; 10<sup>-11</sup>', '<p>&kappa;(salt) = 4.1 - 1.5 = 2.6 &times; 10<sup>-6</sup> S cm<sup>-1</sup>.</p><p>s = &kappa; &times; 1000/&Lambda;&deg;<sub>m</sub> = 2.6 &times; 10<sup>-6</sup> &times; 1000/286 = 9.09 &times; 10<sup>-6</sup> M.</p><p>K<sub>sp</sub> = s<sup>2</sup> = 8.26 &times; 10<sup>-11</sup>, so <b>8.26</b>.</p>', 'Subtract the conductivity of water first.', () => ((4.1e-6 - 1.5e-6) * 1000 / 286) ** 2 / 1e-11);
nat(4, 'conductance and pH', 'A 0.10 M solution of a weak monobasic acid has &kappa; = 1.0 &times; 10<sup>-3</sup> S cm<sup>-1</sup>; &Lambda;&deg;<sub>m</sub> = 400 S cm<sup>2</sup> mol<sup>-1</sup>. Find its pH.', 2.60, 0.02, '', '<p>&Lambda;<sub>m</sub> = 1.0 &times; 10<sup>-3</sup> &times; 1000/0.10 = 10.</p><p>&alpha; = 10/400 = 0.025, [H<sup>+</sup>] = C&alpha; = 0.10 &times; 0.025 = 2.5 &times; 10<sup>-3</sup> M.</p><p>pH = -log(2.5 &times; 10<sup>-3</sup>) = <b>2.60</b>.</p>', '', () => -l10(0.1 * 0.025));
nat(4, 'non-standard Gibbs energy', 'For the Daniell cell with [Zn<sup>2+</sup>] = 1 M and [Cu<sup>2+</sup>] = 0.01 M at 25 &deg;C, find &Delta;G in kJ. E&deg;cell = 1.10 V, 0.059 V, F = 96500.', -200.9, 0.5, 'kJ', '<p>E = 1.10 - 0.0295 log(1/0.01) = 1.10 - 0.059 = 1.041 V.</p><p>&Delta;G = -nFE = -2 &times; 96500 &times; 1.041 = -200913 J = <b>-200.9 kJ</b>.</p>', 'Use E, not E&deg;, for non-standard conditions.', () => -2 * 96500 * (1.10 - 0.0295 * 2) / 1000);
nat(4, 'equilibrium constant', 'Find log K at 25 &deg;C for Sn<sup>2+</sup> + 2Fe<sup>3+</sup> &rarr; Sn<sup>4+</sup> + 2Fe<sup>2+</sup>. E&deg;(Fe<sup>3+</sup>/Fe<sup>2+</sup>) = 0.77 V, E&deg;(Sn<sup>4+</sup>/Sn<sup>2+</sup>) = 0.15 V. (0.059 V)', 21.0, 0.1, '', '<p>E&deg;cell = 0.77 - 0.15 = 0.62 V. Electrons transferred: Sn<sup>2+</sup> loses 2, so n = 2 (two Fe<sup>3+</sup> gain 1 each).</p><p>log K = 2 &times; 0.62/0.059 = <b>21.0</b>.</p>', 'n is the electrons in the balanced equation as written.', () => 2 * 0.62 / 0.059);
nat(4, 'temperature coefficient', 'A cell reaction (n = 2) has E = 1.00 V at 298 K and dE/dT = -5.0 &times; 10<sup>-4</sup> V K<sup>-1</sup>. Find &Delta;H in kJ. (F = 96500)', -221.8, 0.3, 'kJ', '<p>&Delta;G = -nFE = -2 &times; 96500 &times; 1.00 = -193.0 kJ.</p><p>&Delta;S = nF(dE/dT) = 2 &times; 96500 &times; (-5.0 &times; 10<sup>-4</sup>) = -96.5 J/K.</p><p>&Delta;H = &Delta;G + T&Delta;S = -193000 + 298 &times; (-96.5) = -221757 J &asymp; <b>-221.8 kJ</b>.</p>', 'Convert J to kJ at the end.', () => (-2 * 96500 * 1.0 + 298 * 2 * 96500 * -5e-4) / 1000);
nat(4, 'Nernst equation with pH', 'Calculate the reduction potential of MnO<sub>4</sub><sup>-</sup> + 8H<sup>+</sup> + 5e<sup>-</sup> &rarr; Mn<sup>2+</sup> + 4H<sub>2</sub>O at pH 2 when [MnO<sub>4</sub><sup>-</sup>] = [Mn<sup>2+</sup>] = 1 M. E&deg; = 1.51 V; 0.059 V.', 1.32, 0.01, 'V', '<p>E = E&deg; - (0.059/5) log([Mn<sup>2+</sup>]/([MnO<sub>4</sub><sup>-</sup>][H<sup>+</sup>]<sup>8</sup>)).</p><p>[H<sup>+</sup>] = 10<sup>-2</sup>, so [H<sup>+</sup>]<sup>8</sup> = 10<sup>-16</sup> and log(1/10<sup>-16</sup>) = 16.</p><p>E = 1.51 - 0.0118 &times; 16 = <b>1.321 V</b>. Permanganate is a weaker oxidant in less acidic solution.</p>', 'H<sup>+</sup> is raised to the eighth power.', () => 1.51 - 0.059 / 5 * 16);
nat(4, 'conductance of brine electrolysis', 'A current of 10 A is passed for 965 s through brine in a diaphragm cell. What mass of NaOH is formed at the cathode side (Na = 23, O = 16, H = 1)?', 4.0, 0.05, 'g', '<p>Q = 9650 C = 0.1 mol e<sup>-</sup>. Each electron forms one OH<sup>-</sup>: 0.1 mol NaOH.</p><p>Mass = 0.1 &times; 40 = <b>4.0 g</b>.</p>', '', () => 0.1 * 40);
nat(4, 'lead storage battery', 'A lead storage battery delivers 2.0 A for 4825 s. What mass of H<sub>2</sub>SO<sub>4</sub> (M = 98) is consumed? Overall: Pb + PbO<sub>2</sub> + 2H<sub>2</sub>SO<sub>4</sub> &rarr; 2PbSO<sub>4</sub> + 2H<sub>2</sub>O.', 9.8, 0.1, 'g', '<p>Q = 9650 C = 0.1 mol e<sup>-</sup>. The reaction transfers 2 e<sup>-</sup> and uses 2 mol H<sub>2</sub>SO<sub>4</sub>, so 1 mol H<sub>2</sub>SO<sub>4</sub> per mol e<sup>-</sup>.</p><p>Mass = 0.1 &times; 98 = <b>9.8 g</b>.</p>', '', () => 0.1 * 98);
nat(4, 'transport number', 'In NaCl at infinite dilution &Lambda;&deg;<sub>m</sub> = 126.5 S cm<sup>2</sup> mol<sup>-1</sup> and &lambda;&deg;(Cl<sup>-</sup>) = 76.5. Find the transport number of Na<sup>+</sup>.', 0.395, 0.005, '', '<p>&lambda;&deg;(Na<sup>+</sup>) = 126.5 - 76.5 = 50.0.</p><p>t<sub>+</sub> = &lambda;&deg;<sub>+</sub>/&Lambda;&deg;<sub>m</sub> = 50/126.5 = <b>0.395</b>.</p>', 't<sub>+</sub> + t<sub>-</sub> = 1.', () => 50 / 126.5);
mk(4, 'effect of equation scaling', 'The cell reaction Zn + Cu<sup>2+</sup> &rarr; Zn<sup>2+</sup> + Cu is rewritten as 2Zn + 2Cu<sup>2+</sup> &rarr; 2Zn<sup>2+</sup> + 2Cu. Which statement is NOT correct?', 'E&deg;cell becomes twice as large', ['&Delta;G&deg; becomes twice as large', 'K becomes the square of the original K', 'E&deg;cell stays the same'], '<p>E&deg; is intensive: unchanged. &Delta;G&deg; = -nFE&deg; doubles since n doubles. K = 10<sup>nE&deg;/0.059</sup> gets its exponent doubled, i.e. K&rarr;K<sup>2</sup>. Only "E&deg; becomes twice" is wrong, and it is the question\'s "NOT correct" answer.</p>', 'Reading "NOT correct" as "correct".');
mk(4, 'coexistence of species', 'Which pair can NOT exist together in solution under standard conditions? (E&deg;: Ag<sup>+</sup>/Ag +0.80, Cu<sup>2+</sup>/Cu +0.34, Zn<sup>2+</sup>/Zn -0.76, Fe<sup>3+</sup>/Fe<sup>2+</sup> +0.77, Ni<sup>2+</sup>/Ni -0.25 V)', 'Ag<sup>+</sup> and Cu(s)', ['Cu<sup>2+</sup> and Fe<sup>2+</sup>', 'Zn<sup>2+</sup> and Ni(s)', 'Ni<sup>2+</sup> and Cu(s)'], '<p>Two species react if the oxidiser has a higher E&deg; than the reducing agent\'s couple. Ag<sup>+</sup> (0.80) oxidises Cu (0.34): E&deg;cell = +0.46 V, so they react. Cu<sup>2+</sup> (0.34) cannot oxidise Fe<sup>2+</sup> to Fe<sup>3+</sup> (0.77). Zn<sup>2+</sup> cannot oxidise Ni; Ni<sup>2+</sup> cannot oxidise Cu. Those pairs coexist.</p>');
mk(4, 'order of deposition', 'An aqueous solution contains 1 M each of Au<sup>3+</sup>, Ag<sup>+</sup>, Cu<sup>2+</sup> and Zn<sup>2+</sup> (E&deg; +1.50, +0.80, +0.34, -0.76 V). As the cathode potential is lowered gradually, the order in which metals appear is', 'Au, Ag, Cu (and then H<sub>2</sub> rather than Zn)', ['Zn, Cu, Ag, Au', 'Ag, Au, Cu, Zn', 'Cu, Ag, Au, then Zn'], '<p>The ion with the highest reduction potential is reduced first: Au<sup>3+</sup> (+1.50), then Ag<sup>+</sup> (+0.80), then Cu<sup>2+</sup> (+0.34). Water is reduced before Zn<sup>2+</sup> (-0.76 V), so H<sub>2</sub> appears rather than zinc on an inert cathode in dilute solution.</p>');
mk(4, 'salt bridge choice', 'A salt bridge for a cell with an AgNO<sub>3</sub> half-cell should contain', 'KNO<sub>3</sub>, because K<sup>+</sup> and NO<sub>3</sub><sup>-</sup> have similar mobilities and do not react with Ag<sup>+</sup>', ['KCl, because it is the most common salt', 'NaOH, because OH<sup>-</sup> is highly mobile', 'AgCl, because it matches the half-cell'], '<p>A good salt bridge electrolyte has cation and anion mobilities nearly equal (K<sup>+</sup> 73.5, NO<sub>3</sub><sup>-</sup> 71.4) and must not react with the cell. KCl would precipitate AgCl; NaOH would precipitate Ag<sub>2</sub>O; AgCl is insoluble.</p>');
mk(4, 'complex formation and emf', 'In the cell Zn|Zn<sup>2+</sup>(1 M)||Cu<sup>2+</sup>(1 M)|Cu, excess aqueous NH<sub>3</sub> is added to the copper half-cell, forming [Cu(NH<sub>3</sub>)<sub>4</sub>]<sup>2+</sup>. The emf', 'decreases, because [Cu<sup>2+</sup>] falls', ['increases, because the complex is a stronger oxidant', 'stays 1.10 V, because E&deg; is constant', 'increases, because NH<sub>3</sub> is a reducing agent'], '<p>Complexation lowers free [Cu<sup>2+</sup>]. E(Cu<sup>2+</sup>/Cu) = 0.34 + 0.0295 log[Cu<sup>2+</sup>] falls, so E<sub>cell</sub> = E<sub>cathode</sub> - E<sub>anode</sub> decreases. E&deg; applies only at 1 M free Cu<sup>2+</sup>.</p>', 'E&deg; is not the same as E.');
mk(4, 'conductometric titration', 'During a conductometric titration of HCl with NaOH solution added from a burette, the conductance of the solution', 'falls steadily until the equivalence point and rises after it', ['rises steadily until the equivalence point and falls after it', 'stays constant until the equivalence point and then rises', 'rises throughout'], '<p>Before the end point, fast H<sup>+</sup> (350) is replaced by slow Na<sup>+</sup> (50), so conductance falls. After the end point, free OH<sup>-</sup> (199) is added, so it rises. The minimum is at the equivalence point, giving a V-shaped graph.</p>');
mk(4, 'electroplating', 'Zinc can be electroplated from aqueous solution even though E&deg;(Zn<sup>2+</sup>/Zn) = -0.76 V is lower than that of water reduction. The reason is', 'high overpotential for H<sub>2</sub> evolution on zinc', ['the reduction potential of zinc becomes positive in sulphate solution', 'zinc is more reactive than hydrogen', 'Zn<sup>2+</sup> is reduced at the anode'], '<p>Thermodynamically water should be reduced first, but H<sub>2</sub> formation on a zinc surface is very slow (large overpotential). That lets Zn<sup>2+</sup> be reduced instead at suitable pH and current density. Overpotential is kinetic, not captured by E&deg;.</p>');
mk(4, 'effect of added ions', 'NaCl solution is added to the silver half-cell of Cu|Cu<sup>2+</sup>(1 M)||Ag<sup>+</sup>(1 M)|Ag. The emf of the cell', 'decreases, because AgCl precipitates and [Ag<sup>+</sup>] falls', ['increases, because Cl<sup>-</sup> is a reducing agent', 'stays the same because Na<sup>+</sup> is inert', 'becomes zero immediately'], '<p>Ag<sup>+</sup> + Cl<sup>-</sup> &rarr; AgCl(s) lowers [Ag<sup>+</sup>], so E(Ag<sup>+</sup>/Ag) = 0.80 + 0.059 log[Ag<sup>+</sup>] falls and the emf drops (it becomes zero only if [Ag<sup>+</sup>] drops to about 10<sup>-8</sup> M).</p>');
// ---------- Level 5 ----------
nat(5, 'cell and ionic equilibrium', 'A hydrogen electrode (1 bar H<sub>2</sub>) dipped in 0.100 M weak acid HA is connected to a standard hydrogen electrode and gives an emf of 0.177 V at 25 &deg;C. Find K<sub>a</sub> of HA in units of 10<sup>-6</sup> (0.059 V).', 10.1, 0.15, '&times; 10<sup>-6</sup>', '<p>emf = 0.059 pH, so pH = 0.177/0.059 = 3.00, [H<sup>+</sup>] = 1.0 &times; 10<sup>-3</sup> M.</p><p>HA &rightleftharpoons; H<sup>+</sup> + A<sup>-</sup>: K<sub>a</sub> = (10<sup>-3</sup>)<sup>2</sup>/(0.100 - 0.001) = 1.01 &times; 10<sup>-5</sup> = <b>10.1 &times; 10<sup>-6</sup></b>.</p>', 'Using 0.1 in the denominator gives 10.0, not 10.1. Keep tolerance in mind.', () => (1e-3 ** 2 / 0.099) / 1e-6);
nat(5, 'Ksp from a concentration cell', 'The cell Ag|AgX(s), saturated solution || Ag<sup>+</sup>(0.1 M)|Ag has emf 0.413 V at 25 &deg;C. For the saturated silver salt [Ag<sup>+</sup>] = [X<sup>-</sup>]. Find K<sub>sp</sub> of AgX in units of 10<sup>-16</sup>. (0.059 V)', 1.0, 0.05, '&times; 10<sup>-16</sup>', '<p>E = 0.059 log(0.1/[Ag<sup>+</sup>]<sub>sat</sub>) = 0.413, so log(0.1/s) = 7.</p><p>s = 0.1/10<sup>7</sup> = 10<sup>-8</sup> M. K<sub>sp</sub> = s<sup>2</sup> = <b>1.0 &times; 10<sup>-16</sup></b>.</p>', '', () => (0.1 / 10 ** (0.413 / 0.059)) ** 2 / 1e-16);
nat(5, "Faraday's laws with mixture", 'One litre of solution contains 0.10 mol Ag<sup>+</sup> and 0.10 mol Cu<sup>2+</sup> (with a non-reacting anion). A current of 2.00 A is passed. How long (in seconds) until all the Ag and half the Cu have been deposited? (F = 96500; assume Ag deposits first, then Cu.)', 9650, 0, 's', '<p>Electrons needed: Ag: 0.10 mol &times; 1 = 0.10 mol. Cu (half = 0.05 mol): 0.05 &times; 2 = 0.10 mol. Total = 0.20 mol e<sup>-</sup>.</p><p>Q = 0.20 &times; 96500 = 19300 C. t = Q/I = 19300/2.00 = <b>9650 s</b>.</p>', 'Copper needs two electrons per atom, silver only one.', () => (0.1 + 0.05 * 2) * 96500 / 2);
nat(5, 'electrolysis of water', 'Aqueous K<sub>2</sub>SO<sub>4</sub> is electrolysed with Pt electrodes using 3.00 A for 965 s. Find the total volume of gas (H<sub>2</sub> + O<sub>2</sub>) in mL at STP (22.4 L/mol).', 504, 0, 'mL', '<p>Q = 3 &times; 965 = 2895 C = 0.03 mol e<sup>-</sup>. H<sub>2</sub>: 0.03/2 = 0.015 mol. O<sub>2</sub>: 0.03/4 = 0.0075 mol.</p><p>Total = 0.0225 mol &times; 22400 = <b>504 mL</b>.</p>', '', () => (0.03 / 2 + 0.03 / 4) * 22400);
nat(5, 'equilibrium constant', 'Find log K at 25 &deg;C for Fe + Cu<sup>2+</sup> &rarr; Fe<sup>2+</sup> + Cu. E&deg;(Fe<sup>2+</sup>/Fe) = -0.44 V, E&deg;(Cu<sup>2+</sup>/Cu) = +0.34 V. (0.059 V)', 26.4, 0.1, '', '<p>E&deg;cell = 0.34 - (-0.44) = 0.78 V, n = 2.</p><p>log K = 2 &times; 0.78/0.059 = <b>26.4</b>.</p>', '', () => 2 * 0.78 / 0.059);
nat(5, 'fuel cell', 'An H<sub>2</sub>-O<sub>2</sub> fuel cell delivers 5.0 A for 1 hour. What volume of H<sub>2</sub> at STP (in litres) is consumed? (F = 96500; 22.4 L/mol)', 2.09, 0.02, 'L', '<p>Q = 5.0 &times; 3600 = 18000 C = 0.1865 mol e<sup>-</sup>.</p><p>H<sub>2</sub> &rarr; 2H<sup>+</sup> + 2e<sup>-</sup>: n(H<sub>2</sub>) = 0.0933 mol.</p><p>V = 0.0933 &times; 22.4 = <b>2.09 L</b>.</p>', '', () => 18000 / 96500 / 2 * 22.4);
nat(5, 'complex ion electrode potential', 'Cu<sup>2+</sup> + 2e<sup>-</sup> &rarr; Cu has E&deg; = +0.34 V. The formation constant for Cu<sup>2+</sup> + 4NH<sub>3</sub> &rightleftharpoons; [Cu(NH<sub>3</sub>)<sub>4</sub>]<sup>2+</sup> is 1 &times; 10<sup>12</sup>. Find E&deg; for [Cu(NH<sub>3</sub>)<sub>4</sub>]<sup>2+</sup> + 2e<sup>-</sup> &rarr; Cu + 4NH<sub>3</sub> (0.059 V).', -0.014, 0.003, 'V', '<p>At standard conditions of the complex (1 M complex, 1 M NH<sub>3</sub>), [Cu<sup>2+</sup>] = 1/K<sub>f</sub> = 10<sup>-12</sup> M.</p><p>E&deg;(complex) = 0.34 + 0.0295 log(10<sup>-12</sup>) = 0.34 - 0.354 = <b>-0.014 V</b>.</p>', 'The complex ion is a far weaker oxidant than Cu<sup>2+</sup>.', () => 0.34 + 0.0295 * -12);
nat(5, 'Gibbs energy of formation from cells', 'Two half-cell reductions: Fe<sup>3+</sup> + e<sup>-</sup> &rarr; Fe<sup>2+</sup> (+0.77 V) and Fe<sup>2+</sup> + 2e<sup>-</sup> &rarr; Fe (-0.44 V). Find &Delta;G&deg; (in kJ) for Fe<sup>3+</sup> + 3e<sup>-</sup> &rarr; Fe.', 10.6, 0.3, 'kJ', '<p>&Delta;G&deg;<sub>1</sub> = -1 &times; 96500 &times; 0.77 = -74.3 kJ; &Delta;G&deg;<sub>2</sub> = -2 &times; 96500 &times; (-0.44) = +84.9 kJ.</p><p>&Delta;G&deg; = -74.3 + 84.9 = <b>+10.6 kJ</b> (E&deg; = -0.037 V, positive &Delta;G&deg;).</p>', 'Add &Delta;G&deg;, never E&deg;.', () => (-96500 * 0.77 + 2 * 96500 * 0.44) / 1000);
msq(3, 'galvanic cell', 'In the cell Zn|Zn<sup>2+</sup>||Cu<sup>2+</sup>|Cu, which statements are correct?', ['Electrons flow in the external wire from Zn to Cu', 'Anions of the salt bridge move towards the zinc half-cell', 'The copper electrode is the negative terminal', 'The mass of the zinc electrode decreases as the cell works'], [0, 1, 3], '<p>Zn is the anode: Zn &rarr; Zn<sup>2+</sup> + 2e<sup>-</sup> (A and D true). Positive Zn<sup>2+</sup> builds up in the anode compartment, so anions drift there to balance charge (B true). Cu is the cathode, the positive terminal (C false).</p>');
msq(3, 'electrolysis products', 'Which of these pairs of electrolyte and electrodes give the stated products correctly?', ['Dilute H<sub>2</sub>SO<sub>4</sub>, Pt electrodes: O<sub>2</sub> at the anode', 'Aqueous CuSO<sub>4</sub>, Pt electrodes: Cu at the cathode and O<sub>2</sub> at the anode', 'Aqueous AgNO<sub>3</sub>, Ag electrodes: Ag dissolves at the anode and deposits at the cathode', 'Aqueous NaCl, Pt electrodes: Na at the cathode'], [0, 1, 2], '<p>A, B and C are standard results: water is oxidised in A and B; in C the silver anode itself dissolves. In D, water is reduced (H<sub>2</sub>) not Na<sup>+</sup>, so D is false.</p>');
msq(4, 'Nernst equation', 'Which changes will INCREASE the emf of Zn|Zn<sup>2+</sup>(1 M)||Cu<sup>2+</sup>(1 M)|Cu?', ['Dissolving more CuSO<sub>4</sub> in the cathode compartment', 'Adding NaOH to the anode compartment so that Zn(OH)<sub>2</sub> precipitates', 'Using a larger zinc electrode', 'Dissolving more ZnSO<sub>4</sub> in the anode compartment'], [0, 1], '<p>E = 1.10 - 0.0295 log([Zn<sup>2+</sup>]/[Cu<sup>2+</sup>]). Raising [Cu<sup>2+</sup>] (A) or lowering [Zn<sup>2+</sup>] (B) makes the log smaller, so E rises. Electrode size (C) has no effect. Raising [Zn<sup>2+</sup>] (D) lowers E.</p>');
msq(4, 'weak electrolyte dilution', 'On diluting a weak acid solution at constant temperature, which of the following increase?', ['degree of dissociation', 'molar conductivity', 'conductivity (&kappa;)', 'dissociation constant K<sub>a</sub>'], [0, 1], '<p>&alpha; and &Lambda;<sub>m</sub> increase (Ostwald dilution law). &kappa; decreases because ions per unit volume fall. K<sub>a</sub> depends only on temperature, so it is constant.</p>', 'K<sub>a</sub> is not changed by dilution.');
msq(4, 'electrode potentials', 'Which statements about standard electrode potentials are correct?', ['E&deg; does not change when a half-reaction is multiplied by a constant', '&Delta;G&deg; = -nFE&deg; depends on n', 'E&deg;cell = E&deg;(cathode) - E&deg;(anode)', 'A more positive E&deg; means a stronger reducing agent'], [0, 1, 2], '<p>A, B and C are correct. D is the reverse: a more positive E&deg; means a stronger oxidising agent (the species on the left is more easily reduced).</p>');
msq(4, 'corrosion', 'Which statements about corrosion of iron are correct?', ['At the anode, Fe is oxidised to Fe<sup>2+</sup>', 'Dissolved CO<sub>2</sub> (acidic water) speeds up rusting', 'Salt water slows rusting down', 'Zinc coating protects iron even when the coating is cracked'], [0, 1, 3], '<p>Fe &rarr; Fe<sup>2+</sup> + 2e<sup>-</sup> (A true). More H<sup>+</sup> helps the cathode reaction (B true). Dissolved salts raise conductivity, so rusting is faster in sea water (C false). Zinc is a sacrificial anode (D true).</p>');
msq(5, 'conductometric titration', 'A strong acid HCl is titrated conductometrically with NaOH. Which statements are correct?', ['Conductance decreases before the equivalence point', 'Conductance is at its minimum at the equivalence point', 'Conductance increases after the equivalence point', 'Conductance stays unchanged till the end point'], [0, 1, 2], '<p>Before equivalence: H<sup>+</sup> (&lambda; &asymp; 350) is replaced by Na<sup>+</sup> (&asymp; 50), so conductance drops (A). At the end point the solution is only NaCl, the minimum (B). Extra OH<sup>-</sup> (&asymp; 199) then increases it (C). D is false.</p>');
msq(5, 'batteries and fuel cells', 'Select the correct statements.', ['In the Ni-Cd cell, the overall reaction is Cd + 2Ni(OH)<sub>3</sub> &rarr; CdO + 2Ni(OH)<sub>2</sub> + H<sub>2</sub>O', 'Fuel cells convert chemical energy to electricity with about 70 % efficiency, higher than thermal power stations', 'The Leclanch&eacute; dry cell is a secondary cell', 'In a lead storage battery, PbSO<sub>4</sub> forms at both electrodes on discharge'], [0, 1, 3], '<p>A is the standard Ni-Cd reaction. B: no heat step, so efficiency is higher. C is false: the dry cell is primary. D: Pb + SO<sub>4</sub><sup>2-</sup> &rarr; PbSO<sub>4</sub> at the anode and PbO<sub>2</sub> &rarr; PbSO<sub>4</sub> at the cathode.</p>');

// ---------- Assertion-reason ----------
asr(2, 'conductance', 'The molar conductivity of a strong electrolyte increases when the solution is diluted.', 'On dilution the attraction between oppositely charged ions decreases, so ions move more freely.', 0, '<p>Both true. In a strong electrolyte ionisation is already complete, so the rise is due only to lower inter-ionic attraction (the Debye-H&uuml;ckel-Onsager effect). R explains A.</p>');
asr(3, 'electrolysis', 'Electrolysis of aqueous NaCl gives H<sub>2</sub> at the cathode and not sodium.', 'The reduction potential of Na<sup>+</sup> is higher than that of water.', 2, '<p>A is true. R is false: E&deg;(Na<sup>+</sup>/Na) = -2.71 V is much <i>lower</i> than the reduction potential of water (about -0.83 V at pH 14), so water is reduced instead.</p>');
asr(3, 'single electrode potential', 'The absolute potential of a single electrode cannot be measured.', 'A half-cell cannot work alone: oxidation and reduction must occur together in a complete circuit.', 0, '<p>Both true. Only potential <i>differences</i> are measurable, so a reference (SHE) is defined as zero. R explains why a single electrode can never be measured on its own.</p>');
asr(4, 'weak electrolytes', '&Lambda;&deg;<sub>m</sub> of a weak electrolyte cannot be found by extrapolating a plot of &Lambda;<sub>m</sub> versus &radic;c to zero concentration.', '&Lambda;<sub>m</sub> of a weak electrolyte rises very sharply at low concentration, so the plot is not a straight line.', 0, '<p>Both true and R explains A: because &alpha; &rarr; 1 only near infinite dilution, the curve climbs steeply at low c and no reliable intercept exists. Kohlrausch law is used instead.</p>');
asr(3, 'corrosion', 'Zinc protects iron from rusting even when the zinc coating is scratched.', 'Zinc has a more negative reduction potential than iron, so it is oxidised in preference to iron.', 0, '<p>Both true. Zinc acts as the sacrificial anode and iron as the cathode in the moisture film. R is exactly why this happens.</p>');
asr(4, 'salt bridge', 'A KCl salt bridge cannot be used in a cell containing AgNO<sub>3</sub> solution.', 'Ag<sup>+</sup> reacts with Cl<sup>-</sup> to form insoluble AgCl.', 0, '<p>Both true, R explains A. The precipitate would clog the bridge and also change [Ag<sup>+</sup>] and so the emf.</p>');
asr(3, 'conductivity cell', 'The cell constant of a conductivity cell changes when the solution in it is changed.', 'The cell constant depends on the distance between the electrodes and their area.', 3, '<p>A is false: the cell constant l/A depends only on the geometry of the cell, not on what is inside it. R is true.</p>', 'Resistance changes with the solution, not the cell constant.');
asr(2, 'fuel cells', 'Fuel cells are more efficient than thermal power stations.', 'Fuel cells convert the energy of a fuel directly into electrical energy without a heat stage.', 0, '<p>Both true. A thermal plant is limited by the Carnot efficiency of its heat engine (about 40 %), while fuel cells reach about 70 %. R explains A.</p>');
asr(5, 'concentration cell', 'A concentration cell has E&deg;cell = 0 but its emf is not zero.', 'The emf of a concentration cell depends on the ratio of the ion concentrations at the two electrodes.', 0, '<p>Both true. Same metal and same ion means E&deg;(cathode) = E&deg;(anode), so E&deg;cell = 0. The emf comes entirely from the Nernst term (0.059/n) log(c<sub>2</sub>/c<sub>1</sub>), so R explains A.</p>');
asr(4, 'Gibbs energy', 'For the reaction at E&deg;cell = +0.5 V, the &Delta;G&deg; is negative, and the reaction must therefore occur rapidly.', 'A negative &Delta;G&deg; means the reaction is spontaneous.', 3, '<p>A is false (first half true, "must occur rapidly" false): thermodynamics gives direction only, not rate. R is a true statement of definition, but A as a whole is false.</p>', 'Spontaneous does not mean fast.');

// ---------- Statement-based ----------
stm(2, 'salt bridge', 'A salt bridge may contain KCl.', 'K<sup>+</sup> and Cl<sup>-</sup> have nearly equal ionic mobilities, so the liquid junction potential is very small.', 0, '<p>Both correct: K<sup>+</sup> (73.5) and Cl<sup>-</sup> (76.3 S cm<sup>2</sup> mol<sup>-1</sup>) migrate at almost equal speeds.</p>');
stm(3, 'galvanic cell', 'In the Daniell cell the zinc electrode is the negative pole.', 'Electrons flow in the external wire from the copper electrode to the zinc electrode.', 1, '<p>Statement I is correct (zinc is the anode, the negative pole). Statement II is wrong: electrons flow from zinc to copper.</p>');
stm(3, 'conductivity and dilution', 'Conductivity (&kappa;) of a solution increases on dilution.', 'Molar conductivity (&Lambda;<sub>m</sub>) increases on dilution.', 2, '<p>Statement I is wrong: fewer ions per cm<sup>3</sup> lower &kappa;. Statement II is right: &Lambda;<sub>m</sub> = &kappa;/c rises since c falls faster than &kappa;.</p>');
stm(4, 'electrolysis of brine', 'Hydrogen is obtained at the cathode on electrolysing aqueous NaCl.', 'Sodium ions are reduced at the cathode in aqueous NaCl.', 1, '<p>Statement I is correct (water is reduced). Statement II is incorrect: Na<sup>+</sup> is too hard to reduce in water.</p>');
stm(3, 'thermodynamics and kinetics', 'A positive E&deg;cell means a negative &Delta;G&deg;.', 'A reaction with positive E&deg;cell always proceeds at a measurable rate.', 1, '<p>Statement I is true (&Delta;G&deg; = -nFE&deg;). Statement II is false: E&deg; says nothing about the rate. Hydrogen and oxygen are very reactive thermodynamically but need a spark.</p>');
stm(4, 'secondary cells', 'A lead storage battery can be recharged.', 'During recharging it works as an electrolytic cell and the discharge reactions are reversed.', 0, '<p>Both correct. An external source drives current backwards: PbSO<sub>4</sub> goes back to Pb and PbO<sub>2</sub> and the acid is regenerated.</p>');
stm(4, 'weak electrolytes', '&Lambda;&deg;<sub>m</sub> of acetic acid can be found by extrapolating a plot of &Lambda;<sub>m</sub> versus &radic;c.', 'The plot of &Lambda;<sub>m</sub> versus &radic;c is linear for weak electrolytes.', 3, '<p>Both are incorrect. The plot is linear only for strong electrolytes; for weak ones it rises steeply at low c. &Lambda;&deg;<sub>m</sub> is obtained from Kohlrausch law.</p>');
stm(2, "Faraday's laws", 'One faraday deposits 1 mol of copper from CuSO<sub>4</sub>.', 'Copper(II) needs two electrons to be reduced to copper metal.', 2, '<p>Statement I is incorrect: 1 F = 1 mol e<sup>-</sup> deposits 0.5 mol of Cu. Statement II is correct (and is the reason 2 F deposit 1 mol Cu).</p>');
L.push({ type: 'mcq', level: 4, format: 'statements', exams: EXM[4], sub: 'mixed statements', q: '<p>How many of the following are correct?</p><p>(i) The anode of an electrolytic cell is positive.<br>(ii) E&deg; of a half-cell changes if the half-reaction is doubled.<br>(iii) &Lambda;<sub>m</sub> of KCl rises on dilution.<br>(iv) A salt bridge carries electrons between the half-cells.</p>', options: ['Only one', 'Only two', 'Only three', 'All four'], answer: 1, sol: '<p>(i) correct. (ii) wrong: E&deg; is intensive. (iii) correct. (iv) wrong: ions, not electrons, move through a salt bridge. Two are correct.</p>' });
L.push({ type: 'mcq', level: 5, format: 'statements', exams: EXM[5], sub: 'mixed statements', q: '<p>How many of these statements are correct?</p><p>(i) Reduction potentials can be added to get the potential of a combined half-reaction.<br>(ii) For a concentration cell E&deg;cell is zero.<br>(iii) &Delta;G&deg; = -nFE&deg; shows that 1 F carries 96500 C per mole of electrons.<br>(iv) The conductivity of H<sup>+</sup> in water is high because of proton hopping.</p>', options: ['One', 'Two', 'Three', 'Four'], answer: 2, sol: '<p>(i) is wrong: E&deg; values of half-reactions are not additive; &Delta;G&deg; values are. (ii), (iii) and (iv) are correct. So three are correct.</p>', trap: 'Adding E&deg; values directly.' });
// ---------- Match ----------
mat(2, 'electrolysis products', 'm1', 'Match each electrolysis (List I) with the process at its anode (List II).', 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r', 'A-r, B-q, C-p, D-s'], '<p>A: dilute H<sub>2</sub>SO<sub>4</sub> with Pt: water is oxidised to O<sub>2</sub> (p). B: concentrated NaCl with Pt: Cl<sub>2</sub> (q). C: CuSO<sub>4</sub> with Cu electrodes: the copper anode dissolves (r). D: molten PbBr<sub>2</sub>: Br<sup>-</sup> is oxidised to Br<sub>2</sub> (s).</p>');
mat(2, 'units', 'm2', 'Match each quantity (List I) with its unit (List II).', 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-r, C-q, D-s', 'A-p, B-q, C-s, D-r'], '<p>&kappa; is in S cm<sup>-1</sup> (p). &Lambda;<sub>m</sub> = &kappa; &times; 1000/c is in S cm<sup>2</sup> mol<sup>-1</sup> (q). Cell constant l/A is in cm<sup>-1</sup> (r). Resistivity &rho; = 1/&kappa; is in ohm cm (s).</p>');
mat(3, 'batteries', 'm3', 'Match each cell (List I) with its anode (oxidation) reaction (List II).', 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-s, D-r', 'A-p, B-r, C-q, D-s', 'A-s, B-q, C-r, D-p'], '<p>Dry cell: Zn &rarr; Zn<sup>2+</sup> + 2e<sup>-</sup> (p). Lead storage: Pb + SO<sub>4</sub><sup>2-</sup> &rarr; PbSO<sub>4</sub> + 2e<sup>-</sup> (q). Alkaline H<sub>2</sub>-O<sub>2</sub> fuel cell: H<sub>2</sub> + 2OH<sup>-</sup> &rarr; 2H<sub>2</sub>O + 2e<sup>-</sup> (r). Mercury cell: Zn(Hg) + 2OH<sup>-</sup> &rarr; ZnO + H<sub>2</sub>O + 2e<sup>-</sup> (s).</p>');
mat(4, 'Nernst equation', 'm4', 'Match each change to the Daniell cell (List I) with its effect on the emf (List II).', 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r', 'A-r, B-q, C-p, D-s'], '<p>E = 1.10 - 0.0295 log([Zn<sup>2+</sup>]/[Cu<sup>2+</sup>]). A: more Cu<sup>2+</sup> makes the log smaller, so emf rises (p). B: more Zn<sup>2+</sup> lowers it (q). C: electrode size has no effect (r). D: both 1 M gives log 1 = 0, so E = E&deg; = 1.10 V (s).</p>');

// ---------- Passages ----------
PN(3, 'Nernst equation', 'p1', 'Find the emf of the cell.', 1.07, 0.01, 'V', '<p>E = 1.10 - 0.0295 log([Zn<sup>2+</sup>]/[Cu<sup>2+</sup>]) = 1.10 - 0.0295 log(0.1/0.01) = 1.10 - 0.0295 = <b>1.0705 &asymp; 1.07 V</b>.</p>', '', () => 1.10 - 0.0295 * l10(10));
P(3, 'Nernst equation', 'p1', 'If the Cu<sup>2+</sup> solution is diluted tenfold, the emf', 'decreases by about 0.03 V', ['increases by about 0.03 V', 'stays constant', 'decreases by about 0.06 V'], '<p>[Cu<sup>2+</sup>] falls from 0.01 to 0.001 M. The ratio [Zn<sup>2+</sup>]/[Cu<sup>2+</sup>] rises tenfold, so the log term rises by 1 and E falls by 0.0295 V (about 0.03). Option 4 would be right for a hundredfold dilution.</p>');
PN(4, 'Gibbs energy', 'p1', 'Find &Delta;G for the cell reaction (in kJ) under these conditions. F = 96500.', -206.6, 0.5, 'kJ', '<p>&Delta;G = -nFE = -2 &times; 96500 &times; 1.0705 = -206.6 kJ.</p>', 'Use the actual E from the first question.', () => -2 * 96500 * 1.0705 / 1000);
PN(3, 'molar conductivity', 'p2', 'Find the molar conductivity of the acid solution in S cm<sup>2</sup> mol<sup>-1</sup>.', 19.5, 0.1, 'S cm<sup>2</sup> mol<sup>-1</sup>', '<p>&Lambda;<sub>m</sub> = &kappa; &times; 1000/c = 3.9 &times; 10<sup>-4</sup> &times; 1000/0.020 = <b>19.5</b>.</p>', '', () => 3.9e-4 * 1000 / 0.02);
PN(3, 'degree of dissociation', 'p2', 'Find the degree of dissociation &alpha; of the acid.', 0.05, 0.001, '', '<p>&alpha; = &Lambda;<sub>m</sub>/&Lambda;&deg;<sub>m</sub> = 19.5/390 = <b>0.050</b>.</p>', '', () => 19.5 / 390);
PN(4, 'dissociation constant', 'p2', 'Find K<sub>a</sub> of the acid in units of 10<sup>-5</sup>.', 5.26, 0.05, '&times; 10<sup>-5</sup>', '<p>K<sub>a</sub> = C&alpha;<sup>2</sup>/(1 - &alpha;) = 0.020 &times; (0.05)<sup>2</sup>/0.95 = 5.0 &times; 10<sup>-5</sup>/0.95 = <b>5.26 &times; 10<sup>-5</sup></b>.</p>', '', () => 0.02 * 0.0025 / 0.95 / 1e-5);
PN(3, 'electrolysis stoichiometry', 'p3', 'What volume of O<sub>2</sub> (in mL at STP) is released at the anode of cell 1?', 280, 0, 'mL', '<p>Q = 4 &times; 1206.25 = 4825 C = 0.05 mol e<sup>-</sup>. O<sub>2</sub>: 0.05/4 = 0.0125 mol &times; 22400 = <b>280 mL</b>.</p>', '', () => 0.05 / 4 * 22400);
PN(4, 'electrolysis stoichiometry', 'p3', 'What mass of magnesium (Mg = 24.3) is formed in cell 2?', 0.6075, 0.005, 'g', '<p>Mg<sup>2+</sup> + 2e<sup>-</sup> &rarr; Mg: 0.05/2 = 0.025 mol &times; 24.3 = <b>0.6075 g</b>.</p>', 'Same charge flows through both cells.', () => 0.025 * 24.3);
P(3, 'electrolysis stoichiometry', 'p3', 'During the electrolysis, the pH of the CuSO<sub>4</sub> solution in cell 1', 'decreases, because H<sup>+</sup> is produced at the anode', ['increases, because Cu<sup>2+</sup> is removed', 'stays constant', 'increases, because OH<sup>-</sup> is formed at the cathode'], '<p>Anode: 2H<sub>2</sub>O &rarr; O<sub>2</sub> + 4H<sup>+</sup> + 4e<sup>-</sup>. H<sup>+</sup> builds up, so the solution gets more acidic (CuSO<sub>4</sub> becomes H<sub>2</sub>SO<sub>4</sub>). At the cathode only copper deposits; no OH<sup>-</sup> forms.</p>');

// ---------- Extra mixed and conceptual ----------
mk(3, 'mixed: pH and cells', 'A hydrogen half-cell (1 bar) is made with 0.01 M HCl. Its potential at 25 &deg;C versus SHE is', '-0.118 V', ['+0.118 V', '-0.059 V', '-0.0295 V'], '<p>pH = 2, E = -0.059 &times; pH = <b>-0.118 V</b>. It is negative because the less acidic electrode is a better reducing half-cell than SHE.</p>', 'Sign: lower [H<sup>+</sup>] gives a negative E.');
mk(2, 'primary and secondary cells', 'Which of the following is a secondary cell?', 'nickel-cadmium cell', ['mercury cell', 'dry cell', 'alkaline primary cell'], '<p>A secondary cell can be recharged because its reactions are reversible. Ni-Cd, lead storage and lithium-ion cells qualify. Mercury and dry cells are primary (NCERT).</p>');
mk(3, 'galvanic cell', 'A galvanic cell is built from Mg|Mg<sup>2+</sup> and Ag|Ag<sup>+</sup> half-cells at 1 M. If E&deg;(Mg<sup>2+</sup>/Mg) = -2.37 V and E&deg;(Ag<sup>+</sup>/Ag) = +0.80 V, the E&deg;cell is', '3.17 V', ['1.57 V', '-3.17 V', '1.43 V'], '<p>E&deg;cell = 0.80 - (-2.37) = <b>3.17 V</b>. (1.57 would come from adding -2.37 and +0.80, forgetting to change the sign of the anode value.)</p>');
mk(3, 'Faraday laws', 'The ratio of masses of Ag, Cu and Al deposited by the same charge (Ag = 108, Cu = 63.5, Al = 27) is', '108 : 31.75 : 9', ['108 : 63.5 : 27', '1 : 2 : 3', '36 : 31.75 : 27'], '<p>Mass &prop; equivalent mass = M/n: Ag 108/1 = 108, Cu 63.5/2 = 31.75, Al 27/3 = 9. Ratio 108 : 31.75 : 9.</p>');
mk(2, 'electrochemical series', 'A metal M reduces Cu<sup>2+</sup> from solution but cannot reduce Zn<sup>2+</sup>. Its E&deg;(M<sup>2+</sup>/M) must lie between', '-0.76 V and +0.34 V', ['+0.34 V and +0.80 V', 'below -0.76 V', 'above +0.80 V'], '<p>To reduce Cu<sup>2+</sup>, M must have E&deg; lower than +0.34 V. To fail to reduce Zn<sup>2+</sup>, E&deg;(M) must be higher than -0.76 V. So it lies between -0.76 and +0.34 V (e.g. Fe, Ni).</p>');
mk(3, 'conductivity of strong electrolytes', 'Which factor does NOT affect the molar conductivity of a given strong electrolyte solution?', 'the size of the conductivity cell electrodes used for measurement', ['temperature', 'concentration', 'the nature of the solvent'], '<p>&Lambda;<sub>m</sub> is a property of the solution: it depends on temperature, concentration and solvent (viscosity, permittivity). It is found by dividing out the cell constant, so electrode geometry cancels.</p>');
mk(4, 'Nernst equation', 'The emf of a cell is zero. This means the cell', 'is at equilibrium (Q = K)', ['is at standard state', 'has both electrodes at 1 M', 'has E&deg;cell = 0'], '<p>E = 0 means &Delta;G = 0: the reaction has reached equilibrium and Q = K. E&deg;cell is not zero for a normal cell (it equals (0.059/n) log K), and standard state would give E = E&deg;.</p>', 'E = 0 is not E&deg; = 0.');
mk(4, 'concentration cell', 'The emf of a Cu|Cu<sup>2+</sup>(c<sub>1</sub>)||Cu<sup>2+</sup>(c<sub>2</sub>)|Cu cell at 25 &deg;C is 0.0295 V. The ratio c<sub>2</sub>/c<sub>1</sub> is', '10', ['2', '100', '0.1'], '<p>E = (0.059/2) log(c<sub>2</sub>/c<sub>1</sub>) = 0.0295 &times; log ratio. If E = 0.0295, log ratio = 1, so the ratio is 10. (n = 2 for Cu.)</p>');
mk(5, 'conductance vs electrolytes', 'The &Lambda;<sub>m</sub> vs c graphs for HCl, KCl and CH<sub>3</sub>COOH at the same temperature were plotted. Which statement is correct?', 'HCl and KCl lines are nearly straight in &radic;c with negative slope; CH<sub>3</sub>COOH rises steeply at low c', ['All three are straight lines in &radic;c', 'CH<sub>3</sub>COOH is flat while HCl and KCl rise steeply', 'KCl rises steeply while CH<sub>3</sub>COOH is a straight line'], '<p>Strong electrolytes follow &Lambda;<sub>m</sub> = &Lambda;&deg; - A&radic;c. A weak electrolyte rises sharply as c &rarr; 0 because &alpha; &rarr; 1. HCl starts higher than KCl because H<sup>+</sup> conducts better.</p>');
mk(5, 'corrosion', 'An iron nail is partly wrapped with a zinc strip, another with a copper strip, and both are placed in moist salt water. Which statement is correct?', 'The nail with zinc stays protected, while the nail with copper corrodes faster than a bare nail', ['Both nails are protected', 'Both nails corrode faster than a bare nail', 'The nail with copper stays protected while the nail with zinc corrodes faster'], '<p>Zn (-0.76) is more active than Fe (-0.44), so Zn is the anode and corrodes; iron is the cathode and is protected. Cu (+0.34) is less active than Fe, so Fe is the anode and corrodes faster because the Fe/Cu couple drives the cell.</p>');
mk(5, 'Kohlrausch law', 'At infinite dilution &Lambda;&deg;<sub>m</sub> of Ca(OH)<sub>2</sub> is 520 S cm<sup>2</sup> mol<sup>-1</sup> and &lambda;&deg;(Ca<sup>2+</sup>) = 120. The &lambda;&deg;(OH<sup>-</sup>) is', '200 S cm<sup>2</sup> mol<sup>-1</sup>', ['400 S cm<sup>2</sup> mol<sup>-1</sup>', '100 S cm<sup>2</sup> mol<sup>-1</sup>', '300 S cm<sup>2</sup> mol<sup>-1</sup>'], '<p>&Lambda;&deg; = &lambda;&deg;(Ca<sup>2+</sup>) + 2&lambda;&deg;(OH<sup>-</sup>), so 520 = 120 + 2&lambda;&deg;(OH<sup>-</sup>) and &lambda;&deg;(OH<sup>-</sup>) = 200. Forgetting the 2 gives 400.</p>', 'Two OH<sup>-</sup> ions per formula unit.');
mk(5, 'mixed: electrochemistry and equilibrium', 'The E&deg; for AgCl + e<sup>-</sup> &rarr; Ag + Cl<sup>-</sup> is smaller than E&deg;(Ag<sup>+</sup>/Ag). This is because', 'AgCl is sparingly soluble, so [Ag<sup>+</sup>] at 1 M Cl<sup>-</sup> is very small', ['AgCl is more soluble than AgNO<sub>3</sub>', 'Cl<sup>-</sup> is a stronger oxidising agent than NO<sub>3</sub><sup>-</sup>', 'AgCl cannot be reduced'], '<p>At 1 M Cl<sup>-</sup>, [Ag<sup>+</sup>] = K<sub>sp</sub> &asymp; 10<sup>-10</sup> M, so E = 0.80 + 0.059 log(10<sup>-10</sup>) = 0.21 V. The tiny Ag<sup>+</sup> concentration makes silver a weaker oxidant in this electrode.</p>');

const groups = {
  m1: { title: 'Electrolysis and anode process', list1: ['A. Dilute H<sub>2</sub>SO<sub>4</sub>, Pt electrodes', 'B. Concentrated NaCl solution, Pt electrodes', 'C. Aqueous CuSO<sub>4</sub>, Cu electrodes', 'D. Molten PbBr<sub>2</sub>, Pt electrodes'], list2: ['p. O<sub>2</sub> is released', 'q. Cl<sub>2</sub> is released', 'r. The electrode itself dissolves', 's. Br<sub>2</sub> is released'] },
  m2: { title: 'Quantities and their units', list1: ['A. Conductivity &kappa;', 'B. Molar conductivity &Lambda;<sub>m</sub>', 'C. Cell constant', 'D. Resistivity'], list2: ['p. S cm<sup>-1</sup>', 'q. S cm<sup>2</sup> mol<sup>-1</sup>', 'r. cm<sup>-1</sup>', 's. ohm cm'] },
  m3: { title: 'Cells and their anode reactions', list1: ['A. Dry (Leclanch&eacute;) cell', 'B. Lead storage battery', 'C. Alkaline H<sub>2</sub>-O<sub>2</sub> fuel cell', 'D. Mercury cell'], list2: ['p. Zn &rarr; Zn<sup>2+</sup> + 2e<sup>-</sup>', 'q. Pb + SO<sub>4</sub><sup>2-</sup> &rarr; PbSO<sub>4</sub> + 2e<sup>-</sup>', 'r. H<sub>2</sub> + 2OH<sup>-</sup> &rarr; 2H<sub>2</sub>O + 2e<sup>-</sup>', 's. Zn(Hg) + 2OH<sup>-</sup> &rarr; ZnO + H<sub>2</sub>O + 2e<sup>-</sup>'] },
  m4: { title: 'Changes to the Daniell cell Zn|Zn<sup>2+</sup>||Cu<sup>2+</sup>|Cu and the emf', list1: ['A. Increase [Cu<sup>2+</sup>] (cathode side)', 'B. Increase [Zn<sup>2+</sup>] (anode side)', 'C. Double the size of both electrodes', 'D. Keep both solutions at 1 M'], list2: ['p. emf increases', 'q. emf decreases', 'r. emf does not change', 's. emf equals the standard emf, 1.10 V'] },
  p1: { title: 'A non-standard Daniell cell', passage: '<p>The cell Zn|Zn<sup>2+</sup>(0.1 M)||Cu<sup>2+</sup>(0.01 M)|Cu works at 25 &deg;C. E&deg;(Zn<sup>2+</sup>/Zn) = -0.76 V, E&deg;(Cu<sup>2+</sup>/Cu) = +0.34 V, 2.303RT/F = 0.059 V and F = 96500 C/mol.</p>' },
  p2: { title: 'Conductance of a weak acid', passage: '<p>A 0.020 M solution of a weak monobasic acid HA has conductivity 3.9 &times; 10<sup>-4</sup> S cm<sup>-1</sup> at 25 &deg;C. The limiting molar conductivity of HA is &Lambda;&deg;<sub>m</sub> = 390 S cm<sup>2</sup> mol<sup>-1</sup>.</p>' },
  p3: { title: 'Two cells in series', passage: '<p>Two cells are connected in series. Cell 1 contains aqueous CuSO<sub>4</sub> with Pt electrodes. Cell 2 contains molten MgCl<sub>2</sub> with graphite electrodes. A current of 4.00 A passes for 1206.25 s. Take F = 96500 C/mol and molar volume 22.4 L at STP.</p>' },
};

// ---------- Templates ----------
const MET = [
  { s: 'Zn', ion: 'Zn<sup>2+</sup>', E: -0.76, n: 2, M: 65 }, { s: 'Fe', ion: 'Fe<sup>2+</sup>', E: -0.44, n: 2, M: 56 },
  { s: 'Ni', ion: 'Ni<sup>2+</sup>', E: -0.25, n: 2, M: 58.7 }, { s: 'Cd', ion: 'Cd<sup>2+</sup>', E: -0.40, n: 2, M: 112 },
  { s: 'Pb', ion: 'Pb<sup>2+</sup>', E: -0.13, n: 2, M: 207 }, { s: 'Cu', ion: 'Cu<sup>2+</sup>', E: 0.34, n: 2, M: 63.5 },
  { s: 'Mg', ion: 'Mg<sup>2+</sup>', E: -2.37, n: 2, M: 24.3 }, { s: 'Sn', ion: 'Sn<sup>2+</sup>', E: -0.14, n: 2, M: 119 },
];
const DEP = [
  { s: 'Ag', ion: 'Ag<sup>+</sup>', n: 1, M: 108 }, { s: 'Cu', ion: 'Cu<sup>2+</sup>', n: 2, M: 63.5 }, { s: 'Al', ion: 'Al<sup>3+</sup>', n: 3, M: 27 },
  { s: 'Ni', ion: 'Ni<sup>2+</sup>', n: 2, M: 58.7 }, { s: 'Zn', ion: 'Zn<sup>2+</sup>', n: 2, M: 65 },
];
const cstr = (c) => (c >= 1 ? String(c) : `10<sup>${Math.round(l10(c))}</sup>`);
const conc = (c) => (c === 1 ? '1 M' : `${cstr(c)} M`);
const two = (rng, list) => { const i = int(rng, 0, list.length - 1); let j = int(rng, 0, list.length - 2); if (j >= i) j++; return [list[i], list[j]]; };

const gens = [
  { id: 'el-g01', type: 'nat', level: 1, exams: EX[1], sub: 'cell emf',
    make(rng) {
      const [a, b] = two(rng, MET); const lo = a.E < b.E ? a : b, hi = a.E < b.E ? b : a; const ans = +(hi.E - lo.E).toFixed(2);
      return { q: `A cell is made from ${a.s}|${a.ion} and ${b.s}|${b.ion} half-cells at 1 M. E&deg;(${a.ion}/${a.s}) = ${a.E} V and E&deg;(${b.ion}/${b.s}) = ${b.E} V. Find E&deg;<sub>cell</sub>.`, answer: ans, tol: 0.01, unit: 'V', Ea: a.E, Eb: b.E,
        sol: `<p>The metal with the lower (more negative) E&deg; is the anode: ${lo.s}. The other is the cathode: ${hi.s}.</p><p>E&deg;<sub>cell</sub> = ${hi.E} - (${lo.E}) = <b>${ans} V</b>.</p>` };
    }, verify: (p) => +Math.abs(p.Ea - p.Eb).toFixed(2) },
  { id: 'el-g02', type: 'nat', level: 2, exams: EX[2], sub: 'Nernst equation',
    make(rng) {
      let [a, b] = two(rng, MET); if (a.E > b.E) [a, b] = [b, a];
      const ca = choose(rng, [0.001, 0.01, 0.1, 1, 2]); const cc = choose(rng, [0.001, 0.01, 0.1, 1]);
      const E0 = b.E - a.E; const lg = l10(ca / cc); const E = E0 - 0.0295 * lg;
      return { q: `Find the emf at 25 &deg;C of ${a.s}|${a.ion}(${ca} M)||${b.ion}(${cc} M)|${b.s}. E&deg;(${a.ion}/${a.s}) = ${a.E} V, E&deg;(${b.ion}/${b.s}) = ${b.E} V. (2.303RT/F = 0.059 V)`, answer: +E.toFixed(3), tol: 0.005, unit: 'V', E0: +E0.toFixed(2), ca, cc,
        sol: `<p>Reaction: ${a.s} + ${b.ion} &rarr; ${a.ion} + ${b.s}, n = 2; E&deg; = ${b.E} - (${a.E}) = ${E0.toFixed(2)} V.</p><p>E = E&deg; - (0.059/2) log([anode ion]/[cathode ion]) = ${E0.toFixed(2)} - 0.0295 &times; log(${ca}/${cc}) = ${E0.toFixed(2)} - 0.0295 &times; (${lg.toFixed(2)}) = <b>${E.toFixed(3)} V</b>.</p>` };
    }, verify: (p) => p.E0 - 0.0295 * (Math.log10(p.ca) - Math.log10(p.cc)) },
  { id: 'el-g03', type: 'nat', level: 2, exams: EX[2], sub: 'Gibbs energy and emf',
    make(rng) {
      const n = choose(rng, [1, 2, 3, 6]); const E = pick(rng, 0.3, 1.8, 0.05); const dG = -n * 96500 * E / 1000;
      return { q: `A cell reaction involving ${n} electron${n > 1 ? 's' : ''} has E&deg;<sub>cell</sub> = ${E.toFixed(2)} V. Find &Delta;G&deg; in kJ. (F = 96500 C/mol)`, answer: +dG.toFixed(1), tol: 0.3, unit: 'kJ', n, E,
        sol: `<p>&Delta;G&deg; = -nFE&deg; = -${n} &times; 96500 &times; ${E.toFixed(2)} = ${(dG * 1000).toFixed(0)} J = <b>${dG.toFixed(1)} kJ</b>.</p>` };
    }, verify: (p) => -p.n * 96.5 * p.E },
  { id: 'el-g04', type: 'nat', level: 2, exams: EX[2], sub: "Faraday's first law",
    make(rng) {
      const d = choose(rng, DEP); const I = choose(rng, [1, 2, 3, 5]); const t = 965 * pick(rng, 1, 10, 1) * choose(rng, [1, 2]);
      const m = I * t / 96500 / d.n * d.M;
      return { q: `A current of ${I} A is passed for ${t} s through a solution of ${d.ion} ions with inert electrodes. Find the mass of ${d.s} deposited at the cathode. (${d.s} = ${d.M}, F = 96500 C/mol)`, answer: +m.toFixed(3), tol: Math.max(0.005, m * 0.01), unit: 'g', I, t, d,
        sol: `<p>Q = I t = ${I} &times; ${t} = ${I * t} C = ${(I * t / 96500).toFixed(4)} mol of electrons.</p><p>${d.ion} + ${d.n}e<sup>-</sup> &rarr; ${d.s}: n(${d.s}) = ${(I * t / 96500).toFixed(4)}/${d.n} = ${(I * t / 96500 / d.n).toFixed(4)} mol.</p><p>Mass = ${(I * t / 96500 / d.n).toFixed(4)} &times; ${d.M} = <b>${m.toFixed(3)} g</b>.</p>` };
    }, verify: (p) => p.I * p.t * p.d.M / (p.d.n * 96500) },
  { id: 'el-g05', type: 'nat', level: 2, exams: EX[2], sub: "Faraday's laws",
    make(rng) {
      const d = choose(rng, DEP); const ne = choose(rng, [0.01, 0.02, 0.05, 0.1]); const I = choose(rng, [0.5, 1, 2, 5]);
      const m = ne / d.n * d.M; const t = ne * 96500 / I;
      return { q: `For how many seconds must a steady current of ${I} A flow to deposit ${m.toFixed(3)} g of ${d.s} from a solution of ${d.ion}? (${d.s} = ${d.M}, F = 96500 C/mol)`, answer: +t.toFixed(1), tol: Math.max(1, t * 0.005), unit: 's', ne, I,
        sol: `<p>n(${d.s}) = ${m.toFixed(3)}/${d.M} = ${(m / d.M).toFixed(5)} mol; each needs ${d.n} e<sup>-</sup>, so electrons = ${ne.toFixed(2)} mol.</p><p>Q = ${ne} &times; 96500 = ${(ne * 96500).toFixed(0)} C; t = Q/I = ${(ne * 96500).toFixed(0)}/${I} = <b>${t.toFixed(0)} s</b>.</p>` };
    }, verify: (p) => p.ne * 96500 / p.I },
  { id: 'el-g06', type: 'nat', level: 2, exams: EX[2], sub: 'molar conductivity',
    make(rng) {
      const k = pick(rng, 2, 20, 1) / 1000; const c = choose(rng, [0.01, 0.02, 0.05, 0.1, 0.2]); const L = k * 1000 / c;
      return { q: `A ${c} M solution of an electrolyte has conductivity ${k} S cm<sup>-1</sup>. Find its molar conductivity in S cm<sup>2</sup> mol<sup>-1</sup>.`, answer: +L.toFixed(2), tol: Math.max(0.05, L * 0.005), unit: 'S cm<sup>2</sup> mol<sup>-1</sup>', k, c,
        sol: `<p>&Lambda;<sub>m</sub> = &kappa; &times; 1000/c = ${k} &times; 1000/${c} = <b>${L.toFixed(2)}</b> S cm<sup>2</sup> mol<sup>-1</sup>.</p>` };
    }, verify: (p) => p.k * 1000 / p.c },
  { id: 'el-g07', type: 'nat', level: 2, exams: EX[2], sub: 'cell constant',
    make(rng) {
      const G = pick(rng, 1, 4, 0.25); const R = choose(rng, [100, 200, 250, 400, 500, 800]); const k = G / R;
      return { q: `A conductivity cell has cell constant ${G} cm<sup>-1</sup>. The solution in it has resistance ${R} &Omega;. Find the conductivity in units of 10<sup>-3</sup> S cm<sup>-1</sup>.`, answer: +(k * 1000).toFixed(3), tol: Math.max(0.005, k * 1000 * 0.005), unit: '&times; 10<sup>-3</sup> S cm<sup>-1</sup>', G, R,
        sol: `<p>&kappa; = G*/R = ${G}/${R} = ${k.toFixed(5)} S cm<sup>-1</sup> = <b>${(k * 1000).toFixed(3)} &times; 10<sup>-3</sup></b>.</p>` };
    }, verify: (p) => p.G / p.R * 1000 },
  { id: 'el-g08', type: 'nat', level: 2, exams: EX[2], sub: 'Kohlrausch law',
    make(rng) {
      const kcl = pick(rng, 140, 150, 1); const nacl = pick(rng, 118, 128, 1); const kx = pick(rng, 100, 160, 1);
      const names = choose(rng, [['KNO<sub>3</sub>', 'sodium nitrate'], ['KBr', 'NaBr'], ['KI', 'NaI'], ['KOH', 'NaOH']]);
      const ans = nacl + kx - kcl;
      return { q: `Limiting molar conductivities (S cm<sup>2</sup> mol<sup>-1</sup>): KCl = ${kcl}, NaCl = ${nacl}, ${names[0]} = ${kx}. Find &Lambda;&deg;<sub>m</sub> of ${names[1]}.`, answer: ans, tol: 0, unit: 'S cm<sup>2</sup> mol<sup>-1</sup>', kcl, nacl, kx,
        sol: `<p>${names[1]} = NaCl + ${names[0]} - KCl, because the K<sup>+</sup> and Cl<sup>-</sup> terms cancel.</p><p>= ${nacl} + ${kx} - ${kcl} = <b>${ans}</b>.</p>` };
    }, verify: (p) => p.nacl - p.kcl + p.kx },
  { id: 'el-g09', type: 'nat', level: 3, exams: EX[3], sub: 'weak electrolyte',
    make(rng) {
      const a = choose(rng, [0.02, 0.04, 0.05, 0.1]); const C = choose(rng, [0.01, 0.02, 0.05, 0.1]); const L0 = choose(rng, [350, 390, 400, 410]);
      const Lm = a * L0; const Ka = C * a * a / (1 - a);
      return { q: `A ${C} M weak monobasic acid has molar conductivity ${Lm.toFixed(1)} S cm<sup>2</sup> mol<sup>-1</sup>; &Lambda;&deg;<sub>m</sub> = ${L0}. Find K<sub>a</sub> in units of 10<sup>-5</sup>.`, answer: +(Ka / 1e-5).toPrecision(4), tol: Ka / 1e-5 * 0.01, unit: '&times; 10<sup>-5</sup>', a, C,
        sol: `<p>&alpha; = ${Lm.toFixed(1)}/${L0} = ${a}.</p><p>K<sub>a</sub> = C&alpha;<sup>2</sup>/(1 - &alpha;) = ${C} &times; ${a}<sup>2</sup>/${(1 - a).toFixed(2)} = ${fmt(Ka, 3)} = <b>${fmt(Ka / 1e-5, 3)} &times; 10<sup>-5</sup></b>.</p>` };
    }, verify: (p) => p.C * p.a * p.a / (1 - p.a) / 1e-5 },
  { id: 'el-g10', type: 'nat', level: 3, exams: EX[3], sub: 'equilibrium constant',
    make(rng) {
      const n = choose(rng, [1, 2, 3, 4]); const E = pick(rng, 0.2, 1.3, 0.05); const lk = n * E / 0.059;
      return { q: `A cell reaction with n = ${n} has E&deg;<sub>cell</sub> = ${E.toFixed(2)} V at 298 K. Find log<sub>10</sub>K. (2.303RT/F = 0.059 V)`, answer: +lk.toFixed(2), tol: 0.05, n, E,
        sol: `<p>E&deg; = (0.059/n) log K, so log K = nE&deg;/0.059 = ${n} &times; ${E.toFixed(2)}/0.059 = <b>${lk.toFixed(2)}</b>.</p>` };
    }, verify: (p) => p.n * p.E / 0.059 },
  { id: 'el-g11', type: 'nat', level: 3, exams: EX[3], sub: 'concentration cell',
    make(rng) {
      const mt = choose(rng, [['Cu', 'Cu<sup>2+</sup>', 2], ['Zn', 'Zn<sup>2+</sup>', 2], ['Ag', 'Ag<sup>+</sup>', 1], ['Ni', 'Ni<sup>2+</sup>', 2]]);
      const e1 = int(rng, -4, -1); const e2 = int(rng, e1 + 1, 0); const c1 = 10 ** e1, c2 = 10 ** e2; const E = 0.059 / mt[2] * (e2 - e1);
      return { q: `Find the emf at 25 &deg;C of the concentration cell ${mt[0]}|${mt[1]}(10<sup>${e1}</sup> M)||${mt[1]}(${e2 === 0 ? '1' : '10<sup>' + e2 + '</sup>'} M)|${mt[0]}. (0.059 V)`, answer: +E.toFixed(4), tol: 0.002, unit: 'V', e1, e2, nn: mt[2],
        sol: `<p>E&deg; = 0 for identical electrodes; n = ${mt[2]}.</p><p>E = (0.059/${mt[2]}) log(c<sub>cathode</sub>/c<sub>anode</sub>) = (0.059/${mt[2]}) &times; (${e2} - (${e1})) = <b>${E.toFixed(4)} V</b>.</p>` };
    }, verify: (p) => 0.059 / p.nn * (p.e2 - p.e1) },
  { id: 'el-g12', type: 'nat', level: 3, exams: EX[3], sub: 'pH from cell emf',
    make(rng) {
      const pH = pick(rng, 1, 6, 0.5); const E = 0.059 * pH;
      return { q: `A hydrogen electrode (1 bar H<sub>2</sub>) in a solution of unknown pH is joined to a SHE, and the emf is ${E.toFixed(4)} V with the unknown electrode negative. Find the pH of the solution (0.059 V at 25 &deg;C).`, answer: pH, tol: 0.02, E,
        sol: `<p>The electrode potential is E = -0.059 pH, and the SHE is at 0 V, so emf = 0.059 pH.</p><p>pH = ${E.toFixed(4)}/0.059 = <b>${pH}</b>.</p>` };
    }, verify: (p) => p.E / 0.059 },
  { id: 'el-g13', type: 'mcq', level: 2, exams: EXM[2], sub: 'spontaneity of reactions',
    make(rng) {
      const pool = [...MET].sort((x, y) => x.E - y.E); const idx = [0, 1, 2, 3, 4, 5, 6, 7]; const sel = [];
      while (sel.length < 4) { const k = int(rng, 0, 7); if (!sel.includes(k)) sel.push(k); }
      sel.sort((x, y) => x - y); const m = sel.map((k) => pool[k]);
      const rx = (x, y) => `${x.s} + ${y.ion} &rarr; ${x.ion} + ${y.s}`;
      const o = shuffleOpts(rng, rx(m[0], m[1]), [rx(m[3], m[2]), rx(m[2], m[0]), rx(m[3], m[1])]);
      return { q: `Using standard potentials (${m.map((x) => `${x.s}: ${x.E} V`).join(', ')}), which reaction occurs spontaneously under standard conditions?`, options: o.options, answer: o.answer,
        sol: `<p>A metal reduces the ion of a metal with a higher E&deg;. Order from lowest: ${m.map((x) => x.s).join(' &lt; ')}.</p><p>${m[0].s} (${m[0].E} V) can reduce ${m[1].ion} (${m[1].E} V): E&deg;cell = ${(m[1].E - m[0].E).toFixed(2)} V &gt; 0, so <b>${rx(m[0], m[1])}</b> is spontaneous. The other options have a metal trying to reduce an ion with a lower E&deg;, which gives negative E&deg;cell.</p>` };
    } },
  { id: 'el-g14', type: 'mcq', level: 2, exams: EXM[2], sub: 'electrolysis of aqueous solutions',
    make(rng) {
      const c = choose(rng, [['AgNO<sub>3</sub>', 'Ag metal', 'Ag<sup>+</sup> (+0.80 V) is easier to reduce than water'], ['CuSO<sub>4</sub>', 'Cu metal', 'Cu<sup>2+</sup> (+0.34 V) is easier to reduce than water'], ['Au(NO<sub>3</sub>)<sub>3</sub>', 'Au metal', 'Au<sup>3+</sup> (+1.50 V) is easier to reduce than water'], ['Na<sub>2</sub>SO<sub>4</sub>', 'H<sub>2</sub> gas', 'Na<sup>+</sup> (-2.71 V) is much harder to reduce than water'], ['KNO<sub>3</sub>', 'H<sub>2</sub> gas', 'K<sup>+</sup> (-2.93 V) is much harder to reduce than water'], ['MgSO<sub>4</sub>', 'H<sub>2</sub> gas', 'Mg<sup>2+</sup> (-2.37 V) is much harder to reduce than water'], ['Al<sub>2</sub>(SO<sub>4</sub>)<sub>3</sub>', 'H<sub>2</sub> gas', 'Al<sup>3+</sup> (-1.66 V) is not reduced from water solution']]);
      const metal = c[1].endsWith('metal'); const mname = c[1].split(' ')[0];
      const wr = metal ? ['H<sub>2</sub> gas', 'O<sub>2</sub> gas', 'NO<sub>2</sub> gas'] : ['O<sub>2</sub> gas', 'the metal', 'SO<sub>2</sub> gas'];
      const o = shuffleOpts(rng, c[1], wr.map((w) => (w === 'the metal' ? 'the metal of the salt' : w)));
      return { q: `The product at the cathode when an aqueous solution of ${c[0]} is electrolysed with platinum electrodes is`, options: o.options, answer: o.answer,
        sol: `<p>At the cathode the species with the higher reduction potential is reduced first. ${c[2]}, so the cathode product is <b>${c[1]}</b>. O<sub>2</sub> forms only at the anode.</p>` };
    } },
  { id: 'el-g15', type: 'nat', level: 4, exams: EX[4], sub: 'Ksp from conductance',
    make(rng) {
      const s = pick(rng, 1, 2.5, 0.5) * 1e-5; const L0 = choose(rng, [120, 138, 140, 150]); const kw = choose(rng, [0.5e-6, 1e-6, 1.5e-6]);
      const ks = s * L0 / 1000; const ksol = ks + kw; const Ksp = s * s;
      return { q: `A saturated solution of a sparingly soluble 1:1 salt has conductivity ${fmt(ksol, 4)} S cm<sup>-1</sup>; the water used has ${fmt(kw, 3)} S cm<sup>-1</sup>. &Lambda;&deg;<sub>m</sub> of the salt = ${L0} S cm<sup>2</sup> mol<sup>-1</sup>. Find K<sub>sp</sub> in units of 10<sup>-10</sup>.`, answer: +(Ksp / 1e-10).toPrecision(4), tol: Ksp / 1e-10 * 0.03, unit: '&times; 10<sup>-10</sup>', s, ksol, kw, L0,
        sol: `<p>&kappa;(salt) = ${fmt(ksol, 4)} - ${fmt(kw, 3)} = ${fmt(ks, 4)} S cm<sup>-1</sup>.</p><p>s = &kappa; &times; 1000/&Lambda;&deg;<sub>m</sub> = ${fmt(ks, 4)} &times; 1000/${L0} = ${fmt(s, 3)} M.</p><p>K<sub>sp</sub> = s<sup>2</sup> = ${fmt(Ksp, 3)} = <b>${fmt(Ksp / 1e-10, 3)} &times; 10<sup>-10</sup></b>.</p>` };
    }, verify: (p) => ((p.ksol - p.kw) * 1000 / p.L0) ** 2 / 1e-10 },
  { id: 'el-g16', type: 'nat', level: 3, exams: EX[3], sub: "Faraday's second law",
    make(rng) {
      const [a, b] = two(rng, DEP); const ma = pick(rng, 1, 10, 1) / 2;
      const mb = ma / (a.M / a.n) * (b.M / b.n);
      return { q: `The same charge passes through two cells in series, one depositing ${a.s} from ${a.ion} and the other ${b.s} from ${b.ion}. If ${ma} g of ${a.s} is deposited (${a.s} = ${a.M}, ${b.s} = ${b.M}), find the mass of ${b.s} deposited.`, answer: +mb.toPrecision(3), tol: mb * 0.01, unit: 'g', ma, a, b,
        sol: `<p>Same charge means the masses are in the ratio of equivalent masses (M/n).</p><p>E(${a.s}) = ${a.M}/${a.n} = ${(a.M / a.n).toFixed(2)}; E(${b.s}) = ${b.M}/${b.n} = ${(b.M / b.n).toFixed(2)}.</p><p>m(${b.s}) = ${ma} &times; ${(b.M / b.n).toFixed(2)}/${(a.M / a.n).toFixed(2)} = <b>${mb.toPrecision(3)} g</b>.</p>` };
    }, verify: (p) => p.ma * (p.b.M / p.b.n) / (p.a.M / p.a.n) },
  { id: 'el-g17', type: 'nat', level: 3, exams: EX[3], sub: 'gas volumes in electrolysis',
    make(rng) {
      const g = choose(rng, [['H<sub>2</sub>', 2, 'cathode', '2H<sup>+</sup> + 2e<sup>-</sup> &rarr; H<sub>2</sub>'], ['O<sub>2</sub>', 4, 'anode', '2H<sub>2</sub>O &rarr; O<sub>2</sub> + 4H<sup>+</sup> + 4e<sup>-</sup>'], ['Cl<sub>2</sub>', 2, 'anode', '2Cl<sup>-</sup> &rarr; Cl<sub>2</sub> + 2e<sup>-</sup>']]);
      const I = choose(rng, [1, 2, 5]); const m = pick(rng, 1, 8, 1); const t = 965 * m / I * 2; const Q = I * t;
      const V = Q / 96500 / g[1] * 22400;
      return { q: `A current of ${I} A flows for ${t} s through an electrolytic cell. What volume of ${g[0]} at STP (in mL) is released at the ${g[2]}? (22.4 L/mol, F = 96500 C/mol)`, answer: +V.toFixed(1), tol: V * 0.01, unit: 'mL', I, t, k: g[1],
        sol: `<p>Q = ${I} &times; ${t} = ${Q} C = ${(Q / 96500).toFixed(3)} mol e<sup>-</sup>.</p><p>${g[3]}: ${g[1]} mol e<sup>-</sup> per mol gas, so n = ${(Q / 96500 / g[1]).toFixed(4)} mol.</p><p>V = ${(Q / 96500 / g[1]).toFixed(4)} &times; 22400 = <b>${V.toFixed(1)} mL</b>.</p>` };
    }, verify: (p) => p.I * p.t / 96500 / p.k * 22400 },
  { id: 'el-g18', type: 'nat', level: 4, exams: EX[4], sub: 'temperature coefficient of emf',
    make(rng) {
      const n = choose(rng, [1, 2, 3]); const E = pick(rng, 0.6, 1.5, 0.1); const dT = -pick(rng, 2, 8, 1) * 1e-4;
      const dG = -n * 96500 * E; const dS = n * 96500 * dT; const dH = dG + 298 * dS;
      return { q: `A cell reaction with n = ${n} has E = ${E.toFixed(2)} V at 298 K and temperature coefficient dE/dT = ${(dT * 1e4).toFixed(0)} &times; 10<sup>-4</sup> V K<sup>-1</sup>. Find &Delta;H in kJ. (F = 96500)`, answer: +(dH / 1000).toFixed(1), tol: 0.3, unit: 'kJ', n, E, dT,
        sol: `<p>&Delta;G = -nFE = ${(dG / 1000).toFixed(1)} kJ.</p><p>&Delta;S = nF(dE/dT) = ${n} &times; 96500 &times; (${dT}) = ${dS.toFixed(1)} J/K.</p><p>&Delta;H = &Delta;G + T&Delta;S = ${(dG / 1000).toFixed(1)} + 298 &times; (${dS.toFixed(1)})/1000 = <b>${(dH / 1000).toFixed(1)} kJ</b>.</p>` };
    }, verify: (p) => (-p.n * 96.5 * p.E) + 298 * p.n * 96.5 * p.dT },
  { id: 'el-g19', type: 'nat', level: 4, exams: EX[4], sub: 'Nernst equation with pH',
    make(rng) {
      const sp = choose(rng, [['MnO<sub>4</sub><sup>-</sup> + 8H<sup>+</sup> + 5e<sup>-</sup> &rarr; Mn<sup>2+</sup> + 4H<sub>2</sub>O', 1.51, 5, 8], ['Cr<sub>2</sub>O<sub>7</sub><sup>2-</sup> + 14H<sup>+</sup> + 6e<sup>-</sup> &rarr; 2Cr<sup>3+</sup> + 7H<sub>2</sub>O', 1.33, 6, 14]]);
      const pH = int(rng, 1, 5); const E = sp[1] - 0.059 / sp[2] * sp[3] * pH;
      return { q: `Find the reduction potential of ${sp[0]} at pH ${pH} with all other species at 1 M. E&deg; = ${sp[1]} V; 0.059 V.`, answer: +E.toFixed(3), tol: 0.006, unit: 'V', E0: sp[1], n: sp[2], h: sp[3], pH,
        sol: `<p>E = E&deg; - (0.059/${sp[2]}) log Q, with Q = 1/[H<sup>+</sup>]<sup>${sp[3]}</sup> = 10<sup>${sp[3] * pH}</sup> (other species 1 M), so log Q = ${sp[3] * pH}.</p><p>E = ${sp[1]} - (0.059/${sp[2]}) &times; ${sp[3] * pH} = <b>${E.toFixed(3)} V</b>.</p>` };
    }, verify: (p) => p.E0 - 0.059 / p.n * p.h * p.pH },
  { id: 'el-g20', type: 'nat', level: 3, exams: EX[3], sub: 'current efficiency',
    make(rng) {
      const d = choose(rng, DEP); const I = choose(rng, [2, 4, 5]); const t = choose(rng, [1800, 3600, 7200]); const eff = choose(rng, [70, 75, 80, 85, 90]);
      const th = I * t / 96500 / d.n * d.M; const act = +(th * eff / 100).toFixed(3); const ans = act / th * 100;
      return { q: `A current of ${I} A is passed for ${t} s to deposit ${d.s} from ${d.ion}, but only ${act} g is collected. Find the current efficiency in % (${d.s} = ${d.M}, F = 96500).`, answer: +ans.toFixed(1), tol: 0.5, unit: '%', I, t, d, act,
        sol: `<p>Theoretical mass = I t M/(nF) = ${I} &times; ${t} &times; ${d.M}/(${d.n} &times; 96500) = ${th.toFixed(3)} g.</p><p>Efficiency = ${act}/${th.toFixed(3)} &times; 100 = <b>${ans.toFixed(1)} %</b>.</p>` };
    }, verify: (p) => p.act / (p.I * p.t * p.d.M / (p.d.n * 96500)) * 100 },
  { id: 'el-g21', type: 'mcq', level: 2, exams: EXM[2], sub: 'electrons in half reactions',
    make(rng) {
      const sp = choose(rng, [['MnO<sub>4</sub><sup>-</sup> to Mn<sup>2+</sup> (acidic medium)', 5], ['Cr<sub>2</sub>O<sub>7</sub><sup>2-</sup> to 2Cr<sup>3+</sup>', 6], ['Fe<sup>3+</sup> to Fe', 3], ['Al<sup>3+</sup> to Al', 3], ['Cu<sup>2+</sup> to Cu', 2], ['ClO<sub>3</sub><sup>-</sup> to Cl<sup>-</sup>', 6], ['MnO<sub>4</sub><sup>-</sup> to MnO<sub>2</sub> (neutral medium)', 3], ['NO<sub>3</sub><sup>-</sup> to NH<sub>3</sub>', 8]]);
      const k = choose(rng, [2, 3]); const ans = sp[1] * k;
      const o = numOpts(rng, ans, [sp[1], 2 * ans, ans + 1], 'F', 3);
      return { q: `How many faradays of charge are needed to convert ${k} mol of ${sp[0]}?`, options: o.options, answer: o.answer,
        sol: `<p>The change needs ${sp[1]} mol of electrons per mole (work out the oxidation-state change).</p><p>For ${k} mol: ${k} &times; ${sp[1]} = <b>${ans} F</b> (1 F = 1 mol of electrons).</p>` };
    } },
  { id: 'el-g22', type: 'nat', level: 2, exams: EX[2], sub: 'equivalent conductivity',
    make(rng) {
      const N = choose(rng, [0.1, 0.2, 0.5, 1]); const k = pick(rng, 5, 40, 1) / 1000; const L = k * 1000 / N;
      return { q: `A ${N} N solution of an electrolyte has conductivity ${k} S cm<sup>-1</sup>. Find its equivalent conductivity in S cm<sup>2</sup> eq<sup>-1</sup>.`, answer: +L.toFixed(2), tol: Math.max(0.05, L * 0.005), unit: 'S cm<sup>2</sup> eq<sup>-1</sup>', N, k,
        sol: `<p>&Lambda;<sub>eq</sub> = &kappa; &times; 1000/N = ${k} &times; 1000/${N} = <b>${L.toFixed(2)}</b>.</p>` };
    }, verify: (p) => p.k * 1000 / p.N },
  { id: 'el-g23', type: 'nat', level: 5, exams: EX[5], sub: 'complex ion electrode potential',
    make(rng) {
      const m = choose(rng, [['Cu<sup>2+</sup>', 'Cu', 0.34, 2], ['Ag<sup>+</sup>', 'Ag', 0.80, 1]]); const e = int(rng, 6, 14);
      const E = m[2] + 0.059 / m[3] * -e;
      return { q: `E&deg;(${m[0]}/${m[1]}) = ${m[2]} V. A ligand forms a complex of ${m[0]} with formation constant 1 &times; 10<sup>${e}</sup>. Find E&deg; of the electrode (complex) + ${m[3]}e<sup>-</sup> &rarr; ${m[1]} + ligand, with 1 M complex and 1 M free ligand. (0.059 V)`, answer: +E.toFixed(3), tol: 0.004, unit: 'V', E0: m[2], n: m[3], e,
        sol: `<p>With 1 M complex and 1 M ligand, [${m[0]}] = 1/K<sub>f</sub> = 10<sup>-${e}</sup> M.</p><p>E = ${m[2]} + (0.059/${m[3]}) log(10<sup>-${e}</sup>) = ${m[2]} - ${(0.059 / m[3] * e).toFixed(3)} = <b>${E.toFixed(3)} V</b>.</p>` };
    }, verify: (p) => p.E0 - 0.059 / p.n * p.e },
];

